select DocumentType,FinalTAB.CreateDate,FinalTAB.CompanyID ,FinalTAB.CustomerID {15} ,case when HRMS_Set_Employee.EmployeeCode is null then UPPER(Name) else UPPER(Name) + ' (' + HRMS_Set_Employee.EmployeeCode + ')' end as Name ,SourceID ,Amount ,UPPER(InstrumentNo) as InstrumentNo ,Upper(Comments) as Comments , UPPER(DetailNarration)as DetailNarration ,InvoiceNumbers ,InvoiceDocumentNo ,DocumentNo ,DocumentDate ,FreightAmount ,ForAlhajAmount ,upper(BPType) as BPType ,GRN_NO,PO_NO, SheetNo, FAX, (select OperatingUnitName from SET_OperatingUnit where OperatingUnitId = FinalTAB.CompanyID) as UnitName from ( select 'Opening' AS DocumentType, @FromDate AS CreateDate,CompanyID, TABopening.CustomerID, TABopening.Name, -1 AS SourceID, SUM(TABopening.Amount) as Amount, '' AS InstrumentNo, '' as Comments, '' as DetailNarration, '' AS InvoiceNumbers, '' AS InvoiceDocumentNo, '' AS DocumentNo, @FromDate AS DocumentDate, 0 AS FreightAmount, 0 AS ForAlhajAmount ,'' as BPType,'' as GRN_NO,'' as PO_NO, '' AS SheetNo, '' AS FAX from ( SELECT FINTAB.DocumentType, Fintab.CreateDate,Fintab.CompanyID, FINTAB.CustomerID, FINTAB.Name, FinTab.SourceID, SUM(FINTAB.Amount) as Amount, FINTAB.InstrumentNo, FINTAB.Comments, FINTAB.InvoiceNumbers, FINTAB.InvoiceDocumentNo, FINTAB.DocumentNo, FINTAB.DocumentDate, FINTAB.FreightAmount, FINTAB.ForAlhajAmount FROM ( Select 'Opening' as DocumentType, @FromDate AS CreateDate,0 as CompanyID, openingTAB.CustomerID, openingTAB.Name, -1 AS SourceID, sum(openingTAB.Amount) as Amount, '' as InstrumentNo, '' as Comments, '' as InvoiceNumbers, '' as InvoiceDocumentNo, '' as DocumentNo, @FromDate as DocumentDate, 0 AS FreightAmount, 0 As ForAlhajAmount From ( ---------- OPENING BALANCE VENDOR INVOICE ---------- SELECT 0 as Amount, AR_SET_Customer.CustomerID, AR_SET_Customer.CustomerName AS Name, AR_ReceiptCustomerDetail.ReceiptCustomerID as SourceID FROM SET_DocumentType INNER JOIN AR_ReceiptTransactionHeader ON SET_DocumentType.CompanyID = AR_ReceiptTransactionHeader.CompanyID AND SET_DocumentType.PeriodID = AR_ReceiptTransactionHeader.PeriodID AND SET_DocumentType.DocumentTypeID = AR_ReceiptTransactionHeader.DocumentTypeID AND AR_ReceiptTransactionHeader.Status = 1 AND AR_ReceiptTransactionHeader.StatusCode = 1 INNER JOIN AR_ReceiptCustomerDetail on AR_ReceiptCustomerDetail.ReceiptHeaderID = AR_ReceiptTransactionHeader.ReceiptTransactionID and AR_ReceiptCustomerDetail.CompanyID = AR_ReceiptTransactionHeader.CompanyID and AR_ReceiptCustomerDetail.PeriodID = AR_ReceiptTransactionHeader.PeriodID and AR_ReceiptCustomerDetail.status = 1 INNER JOIN AR_SET_Customer ON AR_ReceiptCustomerDetail.CustomerID = AR_SET_Customer.CustomerID --AND AR_ReceiptCustomerDetail.CompanyID = AR_SET_Customer.CompanyID AND AR_ReceiptCustomerDetail.PeriodID = AR_SET_Customer.PeriodID AND AR_SET_Customer.Status = 1
INNER JOIN AR_SET_BusinessPartnerTypes ON AR_SET_BusinessPartnerTypes.BusinessPartnerID = AR_SET_Customer.CustomerID --AND AR_SET_BusinessPartnerTypes.CompanyID = AR_SET_Customer.CompanyID AND AR_SET_BusinessPartnerTypes.PeriodID = AR_SET_Customer.PeriodID AND AR_SET_BusinessPartnerTypes.TypeCode = AR_ReceiptCustomerDetail.BusinessPartnerTypeID INNER JOIN AR_SET_BusinessPartner ON AR_SET_BusinessPartner.BusinessPartnerID = AR_SET_BusinessPartnerTypes.TypeCode LEFT Join AR_ReceiptAccountsDetail on AR_ReceiptAccountsDetail.CompanyID = AR_ReceiptTransactionHeader.CompanyID AND AR_ReceiptAccountsDetail.PeriodID = AR_ReceiptTransactionHeader.PeriodID AND AR_ReceiptAccountsDetail.ReceiptHeaderID = AR_ReceiptTransactionHeader.ReceiptTransactionID {7} WHERE AR_ReceiptTransactionHeader.CompanyID in @CompanyID and AR_SET_Customer.PeriodID = @PeriodID AND AR_ReceiptTransactionHeader.DocumentDate < @FromDate And (SET_DocumentType.DocumentTypeID =@DocumentTypeiD Or @DocumentTypeiD is Null) {4} GROUP BY AR_SET_Customer.CustomerID, AR_SET_Customer.CustomerName, AR_ReceiptCustomerDetail.TransactionType, AR_ReceiptCustomerDetail.ReceiptCustomerID ) OpeningTAB GROUP BY OpeningTAB.CustomerID ,OpeningTAB.Name
UNION ALL
select distinct TABInvoice.DocumentType, TABInvoice.CreateDate,CompanyID, TABInvoice.CustomerID, TABInvoice.BusinessPartnerName, TABInvoice.SourceID, TABInvoice.Amount, TABInvoice.InstrumentNo, TABInvoice.Comments, TABInvoice.InvoiceNumbers, TABInvoice.InvoiceDocumentNo, TABInvoice.DocumentNo, TABInvoice.DocumentDate, TABInvoice.FreightAmount, TABInvoice.ForAlhajAmount from ( ---------- Vendor Invoice ---------- SELECT distinct AR_InvoiceHeader.companyID, Set_DocumentType.TransactionType, case when AR_SET_BusinessPartnerTypes.TypeCode is null then ( select top 1 CUS.TypeCode from AR_SET_BusinessPartnerTypes CUS where AR_InvoiceSupplierDetail.SupplierID = CUS.BusinessPartnerID AND AR_InvoiceSupplierDetail.CompanyID = CUS.CompanyID AND AR_InvoiceSupplierDetail.PeriodID = CUS.PeriodID ) else AR_SET_BusinessPartnerTypes.TypeCode end as TypeCode, case when AR_InvoiceHeader.vendorID is null then ( select CUS.CustomerID from AR_SET_Customer CUS where AR_InvoiceSupplierDetail.SupplierID = CUS.CustomerID AND AR_InvoiceSupplierDetail.PeriodID = CUS.PeriodID ) else ( select CUS.CustomerID from AR_SET_Customer CUS where AR_InvoiceHeader.vendorID = CUS.CustomerID AND AR_InvoiceHeader.PeriodID = CUS.PeriodID ) end as CustomerID, SET_DocumentType.DocumentType, AR_InvoiceHeader.CreateDate, case when AR_InvoiceHeader.vendorID is null then ( select CUS.CustomerName from AR_SET_Customer CUS where AR_InvoiceSupplierDetail.SupplierID = CUS.CustomerID AND AR_InvoiceSupplierDetail.PeriodID = CUS.PeriodID ) else ( select CUS.CustomerName from AR_SET_Customer CUS where AR_InvoiceHeader.vendorID = CUS.CustomerID AND AR_InvoiceHeader.PeriodID = CUS.PeriodID ) end as BusinessPartnerName, -- AR_InvoiceSupplierDetail.InvoiceSupplierID as SourceID, CASE WHEN AR_InvoiceHeader.vendorID is null then AR_InvoiceSupplierDetail.InvoiceSupplierID else AR_InvoiceHeader.InvoiceID end as SourceID, --case when AR_InvoiceHeader.vendorID is null then -- (Case when AR_InvoiceSupplierDetail.TransactionType = 'Debit' then AR_InvoiceSupplierDetail.Amount else AR_InvoiceSupplierDetail.Amount * -1 end) -- else -- ( -- Case when AR_InvoiceSupplierDetail.TransactionType = 'Debit' then AR_InvoiceHeader.AmountPaid -- when SET_DocumentType.DocumentType = 'Debit Note' then AR_InvoiceHeader.AmountPaid -- else (Isnull(AR_InvoiceHeader.AmountPaid,0) + Isnull(AR_InvoiceHeader.FreightAmount,0) - ISnull(AR_InvoiceHeader.OtherAmount,0)) * -1 end -- ) end as Amount, case when AR_InvoiceHeader.vendorID is null then (Case when AR_InvoiceSupplierDetail.TransactionType = 'Debit' then AR_InvoiceSupplierDetail.Amount else AR_InvoiceSupplierDetail.Amount * -1 end) else ( Case when AR_InvoiceSupplierDetail.TransactionType = 'Debit' AND AR_InvoiceHeader.vendorID is null then AR_InvoiceHeader.AmountPaid when SET_DocumentType.DocumentType = 'Debit Note' then AR_InvoiceHeader.AmountPaid --else (AR_InvoiceHeader.AmountPaid + AR_InvoiceHeader.FreightAmount - isnull(AR_InvoiceHeader.OtherAmount,0)) * -1 end else ( select case when (select count(*) from SET_Parameter where FieldName = 'MergeTaxes') = 0 then sum(GrossAmount) else sum(NetAmount) end from AR_InvoiceDetail invdtl where invdtl.InvoiceHeaderID = AR_InvoiceHeader.InvoiceID and invdtl.CompanyID = AR_InvoiceHeader.CompanyID and invdtl.PeriodID = AR_InvoiceHeader.PeriodID and invdtl.Status = 1
) * -1 end
) end as Amount, '0' AS InstrumentNo, case when AP_PurchaseOrderHeader.DocumentNumber is not null then Concat(AR_InvoiceHeader.Description ,'PO# ', ((Select top 1 AP_PurchaseOrderHeader.DocumentNumber from AP_PurchaseOrderHeader left join AR_InvoiceDetail on AR_InvoiceDetail.PurchaseOrderHeaderID=AP_PurchaseOrderHeader.POHeaderID And AP_PurchaseOrderHeader.CompanyID=AR_InvoiceDetail.CompanyID And AP_PurchaseOrderHeader.PeriodID=AR_InvoiceDetail.PeriodID And AP_PurchaseOrderHeader.Status=1 Where AR_InvoiceDetail.InvoiceHeaderID=AR_InvoiceHeader.InvoiceID AND AR_InvoiceDetail.CompanyID=AR_InvoiceHeader.CompanyID And AR_InvoiceDetail.PeriodID=AR_InvoiceHeader.PeriodID AND AR_InvoiceDetail.Status=1 )), 'GRN#', (Select top 1 DocumentNo from INV_StockTransactionHeader left Join AR_InvoiceDetail on INV_StockTransactionHeader.StockTransactionID=AR_InvoiceDetail.StockHeaderID AND INV_StockTransactionHeader.CompanyID=AR_InvoiceDetail.CompanyID AND INV_StockTransactionHeader.PeriodID=AR_InvoiceDetail.PeriodID AND INV_StockTransactionHeader.Status=1 Where AR_InvoiceDetail.InvoiceHeaderID=AR_InvoiceHeader.InvoiceID AND AR_InvoiceDetail.CompanyID=AR_InvoiceHeader.CompanyID And AR_InvoiceDetail.PeriodID=AR_InvoiceHeader.PeriodID AND AR_InvoiceDetail.Status=1 ) ) else AR_InvoiceHeader.Description end As Comments, AR_InvoiceHeader.VendorReferenceNumber as InvoiceNumbers, '' as InvoiceDocumentNo, ISNULL(AR_InvoiceHeader.InvoiceNumber, 0) AS DocumentNo, AR_InvoiceHeader.InvoiceDate AS DocumentDate, 0 AS FreightAmount, 0 As ForAlhajAmount FROM SET_DocumentType INNER JOIN AR_InvoiceHeader ON SET_DocumentType.CompanyID = AR_InvoiceHeader.CompanyID AND SET_DocumentType.PeriodID = AR_InvoiceHeader.PeriodID AND SET_DocumentType.DocumentTypeID = AR_InvoiceHeader.InvoiceType AND AR_InvoiceHeader.Status = 1 AND AR_InvoiceHeader.StatusCode = 1 LEFT JOIN AR_InvoiceDetail on AR_InvoiceDetail.CompanyID = AR_InvoiceHeader.CompanyID and AR_InvoiceDetail.PeriodID = AR_InvoiceHeader.PeriodID and AR_InvoiceDetail.InvoiceHeaderID = AR_InvoiceHeader.InvoiceID LEFT JOIN AR_InvoiceSupplierDetail on AR_InvoiceSupplierDetail.CompanyID = AR_InvoiceHeader.CompanyID and AR_InvoiceSupplierDetail.PeriodID = AR_InvoiceHeader.PeriodID and AR_InvoiceSupplierDetail.InvoiceHeaderID = AR_InvoiceHeader.InvoiceID and AR_InvoiceSupplierDetail.status = 1 LEFT JOIN AR_SET_Customer ASCUS ON AR_InvoiceSupplierDetail.SupplierID = ASCUS.CustomerID --AND AR_InvoiceSupplierDetail.CompanyID = ASCUS.CompanyID AND AR_InvoiceSupplierDetail.PeriodID = ASCUS.PeriodID AND ASCUS.Status = 1 left JOIN AR_SET_BusinessPartnerTypes ON AR_SET_BusinessPartnerTypes.BusinessPartnerID = AR_InvoiceHeader.vENDORid --AND AR_SET_BusinessPartnerTypes.CompanyID = AR_InvoiceHeader.CompanyID AND AR_SET_BusinessPartnerTypes.PeriodID = AR_InvoiceHeader.PeriodID AND AR_SET_BusinessPartnerTypes.TypeCode = AR_InvoiceHeader.BusinessPartnerTypeID LEFT JOIN AR_SET_BusinessPartner ON AR_SET_BusinessPartner.BusinessPartnerID = AR_SET_BusinessPartnerTypes.TypeCode
left join AP_PurchaseOrderHeader on AP_PurchaseOrderHeader.POHeaderID=AR_InvoiceDetail.PurchaseOrderHeaderID And AP_PurchaseOrderHeader.CompanyID=AR_InvoiceDetail.CompanyID And AP_PurchaseOrderHeader.PeriodID=AR_InvoiceDetail.PeriodID And AP_PurchaseOrderHeader.Status=1
--left Join INV_StockTransactionHeader on INV_StockTransactionHeader.StockTransactionID=AR_InvoiceDetail.StockHeaderID --AND INV_StockTransactionHeader.CompanyID=AR_InvoiceDetail.CompanyID --AND INV_StockTransactionHeader.PeriodID=AR_InvoiceDetail.PeriodID --AND INV_StockTransactionHeader.Status=1 {7} WHERE AR_InvoiceHeader.CompanyID in @CompanyID AND AR_InvoiceHeader.PeriodID = @PeriodId AND AR_InvoiceHeader.InvoiceDate < @FromDate And (SET_DocumentType.DocumentTypeID =@DocumentTypeiD Or @DocumentTypeiD is Null) {5} --and SET_DocumentType.documenttype not like '%Opening%' ) TABInvoice where TABInvoice.companyID in @CompanyID {8} {9}
union all ---------- Vendor Invoice supplier ---------- select distinct TABInvoice.DocumentType, TABInvoice.CreateDate,CompanyID, TABInvoice.CustomerID, TABInvoice.BusinessPartnerName, TABInvoice.SourceID, TABInvoice.Amount, TABInvoice.InstrumentNo, TABInvoice.Comments, TABInvoice.InvoiceNumbers, TABInvoice.InvoiceDocumentNo, TABInvoice.DocumentNo, TABInvoice.DocumentDate, TABInvoice.FreightAmount, TABInvoice.ForAlhajAmount from ( ---------- Vendor Invoice ---------- SELECT distinct AR_InvoiceHeader.companyID, Set_DocumentType.TransactionType, case when AR_SET_BusinessPartnerTypes.TypeCode is null then ( select top 1 CUS.TypeCode from AR_SET_BusinessPartnerTypes CUS where AR_InvoiceSupplierDetail.SupplierID = CUS.BusinessPartnerID AND AR_InvoiceSupplierDetail.CompanyID = CUS.CompanyID AND AR_InvoiceSupplierDetail.PeriodID = CUS.PeriodID ) else AR_SET_BusinessPartnerTypes.TypeCode end as TypeCode, case when AR_InvoiceHeader.vendorID is null then ( select CUS.CustomerID from AR_SET_Customer CUS where AR_InvoiceSupplierDetail.SupplierID = CUS.CustomerID AND AR_InvoiceSupplierDetail.PeriodID = CUS.PeriodID ) else ( select CUS.CustomerID from AR_SET_Customer CUS where AR_InvoiceHeader.vendorID = CUS.CustomerID AND AR_InvoiceHeader.PeriodID = CUS.PeriodID ) end as CustomerID, SET_DocumentType.DocumentType, AR_InvoiceHeader.CreateDate, case when AR_InvoiceHeader.vendorID is null then ( select CUS.CustomerName from AR_SET_Customer CUS where AR_InvoiceSupplierDetail.SupplierID = CUS.CustomerID AND AR_InvoiceSupplierDetail.PeriodID = CUS.PeriodID ) else ( select CUS.CustomerName from AR_SET_Customer CUS where AR_InvoiceHeader.vendorID = CUS.CustomerID AND AR_InvoiceHeader.PeriodID = CUS.PeriodID ) end as BusinessPartnerName, AR_InvoiceSupplierDetail.InvoiceSupplierID as SourceID, Case when AR_InvoiceSupplierDetail.TransactionType = 'Debit' then AR_InvoiceSupplierDetail.Amount else AR_InvoiceSupplierDetail.Amount * -1 end as Amount, '0' AS InstrumentNo, case when AP_PurchaseOrderHeader.DocumentNumber is not null then Concat(AR_InvoiceHeader.Description ,'PO# ', ((Select top 1 AP_PurchaseOrderHeader.DocumentNumber from AP_PurchaseOrderHeader left join AR_InvoiceDetail on AR_InvoiceDetail.PurchaseOrderHeaderID=AP_PurchaseOrderHeader.POHeaderID And AP_PurchaseOrderHeader.CompanyID=AR_InvoiceDetail.CompanyID And AP_PurchaseOrderHeader.PeriodID=AR_InvoiceDetail.PeriodID And AP_PurchaseOrderHeader.Status=1 Where AR_InvoiceDetail.InvoiceHeaderID=AR_InvoiceHeader.InvoiceID AND AR_InvoiceDetail.CompanyID=AR_InvoiceHeader.CompanyID And AR_InvoiceDetail.PeriodID=AR_InvoiceHeader.PeriodID AND AR_InvoiceDetail.Status=1 )), 'GRN#', (Select top 1 DocumentNo from INV_StockTransactionHeader left Join AR_InvoiceDetail on INV_StockTransactionHeader.StockTransactionID=AR_InvoiceDetail.StockHeaderID AND INV_StockTransactionHeader.CompanyID=AR_InvoiceDetail.CompanyID AND INV_StockTransactionHeader.PeriodID=AR_InvoiceDetail.PeriodID AND INV_StockTransactionHeader.Status=1 Where AR_InvoiceDetail.InvoiceHeaderID=AR_InvoiceHeader.InvoiceID AND AR_InvoiceDetail.CompanyID=AR_InvoiceHeader.CompanyID And AR_InvoiceDetail.PeriodID=AR_InvoiceHeader.PeriodID AND AR_InvoiceDetail.Status=1 ) ) else AR_InvoiceHeader.Description end As Comments, AR_InvoiceHeader.VendorReferenceNumber as InvoiceNumbers, '' as InvoiceDocumentNo, ISNULL(AR_InvoiceHeader.InvoiceNumber, 0) AS DocumentNo, AR_InvoiceHeader.InvoiceDate AS DocumentDate, 0 AS FreightAmount, 0 As ForAlhajAmount FROM SET_DocumentType INNER JOIN AR_InvoiceHeader ON SET_DocumentType.CompanyID = AR_InvoiceHeader.CompanyID AND SET_DocumentType.PeriodID = AR_InvoiceHeader.PeriodID AND SET_DocumentType.DocumentTypeID = AR_InvoiceHeader.InvoiceType AND AR_InvoiceHeader.Status = 1 AND AR_InvoiceHeader.StatusCode = 1 LEFT JOIN AR_InvoiceDetail on AR_InvoiceDetail.CompanyID = AR_InvoiceHeader.CompanyID and AR_InvoiceDetail.PeriodID = AR_InvoiceHeader.PeriodID and AR_InvoiceDetail.InvoiceHeaderID = AR_InvoiceHeader.InvoiceID LEFT JOIN AR_InvoiceSupplierDetail on AR_InvoiceSupplierDetail.CompanyID = AR_InvoiceHeader.CompanyID and AR_InvoiceSupplierDetail.PeriodID = AR_InvoiceHeader.PeriodID and AR_InvoiceSupplierDetail.InvoiceHeaderID = AR_InvoiceHeader.InvoiceID and AR_InvoiceSupplierDetail.status = 1 LEFT JOIN AR_SET_Customer ASCUS ON AR_InvoiceSupplierDetail.SupplierID = ASCUS.CustomerID --AND AR_InvoiceSupplierDetail.CompanyID = ASCUS.CompanyID AND AR_InvoiceSupplierDetail.PeriodID = ASCUS.PeriodID AND ASCUS.Status = 1 left JOIN AR_SET_BusinessPartnerTypes ON AR_SET_BusinessPartnerTypes.BusinessPartnerID = AR_InvoiceHeader.vENDORid --AND AR_SET_BusinessPartnerTypes.CompanyID = AR_InvoiceHeader.CompanyID AND AR_SET_BusinessPartnerTypes.PeriodID = AR_InvoiceHeader.PeriodID AND AR_SET_BusinessPartnerTypes.TypeCode = AR_InvoiceSupplierDetail.BusinessPartnerTypeID LEFT JOIN AR_SET_BusinessPartner ON AR_SET_BusinessPartner.BusinessPartnerID = AR_SET_BusinessPartnerTypes.TypeCode
left join AP_PurchaseOrderHeader on AP_PurchaseOrderHeader.POHeaderID=AR_InvoiceDetail.PurchaseOrderHeaderID And AP_PurchaseOrderHeader.CompanyID=AR_InvoiceDetail.CompanyID And AP_PurchaseOrderHeader.PeriodID=AR_InvoiceDetail.PeriodID And AP_PurchaseOrderHeader.Status=1
--left Join INV_StockTransactionHeader on INV_StockTransactionHeader.StockTransactionID=AR_InvoiceDetail.StockHeaderID --AND INV_StockTransactionHeader.CompanyID=AR_InvoiceDetail.CompanyID --AND INV_StockTransactionHeader.PeriodID=AR_InvoiceDetail.PeriodID --AND INV_StockTransactionHeader.Status=1 {7} WHERE AR_InvoiceHeader.CompanyID in @CompanyID AND AR_InvoiceHeader.PeriodID = @PeriodId AND AR_InvoiceHeader.InvoiceDate < @FromDate And (SET_DocumentType.DocumentTypeID =@DocumentTypeiD Or @DocumentTypeiD is Null) and SET_DocumentType.DocumentType not like '%HR%' and SET_DocumentType.DocumentType not like '%DI-Invoice%' {5} --and SET_DocumentType.documenttype not like '%Opening%' ) TABInvoice where TABInvoice.companyID in @CompanyID {8} {9}
UNION ALL ---------- Payment ---------- SELECT Distinct SET_DocumentType.DocumentType, AP_PaymentHeader.CreateDate,AP_PaymentHeader.CompanyID, AR_SET_Customer.CustomerID, AR_SET_Customer.CustomerName AS BusinessPartnerName, AP_PaymentSupplierDetail.PaymentSupplierID as SourceID, (Case AP_PaymentSupplierDetail.TransactionType when 'Debit' then AP_PaymentSupplierDetail.Amount else AP_PaymentSupplierDetail.Amount * -1 end) as Amount,
STUFF((SELECT ', ' + PBD.InstrumentNo FROM AP_PaymentBanksDetail PBD WHERE PBD.PaymentHeaderID = AP_PaymentHeader.PaymentID FOR XML PATH('')), 1, 1, '') AS InstrumentNo, IsNull(AP_PaymentHeader.Comments, '') + (Case When AP_PaymentHeader.ReversalComments IS NULL Then '' Else ' ' + AP_PaymentHeader.ReversalComments End) AS Comments,
case when AP_PaymentHeader.POHeaderID is null then (ISNULL( ( SELECT STUFF( ( SELECT AR_InvoiceHeader.InvoiceNumber FROM AP_PaymentHeader childPayment LEFT JOIN AP_PaymentInvoicesDetail ON AP_PaymentInvoicesDetail.PaymentHeaderID = childPayment.PaymentID AND AP_PaymentInvoicesDetail.CompanyID = childPayment.CompanyID AND AP_PaymentInvoicesDetail.PeriodID = childPayment.PeriodID LEFT JOIN AR_InvoiceHeader ON AR_InvoiceHeader.InvoiceID = AP_PaymentInvoicesDetail.InvoiceHeaderID AND AR_InvoiceHeader.CompanyID = AP_PaymentInvoicesDetail.CompanyID AND AR_InvoiceHeader.PeriodID = AP_PaymentInvoicesDetail.PeriodID LEFT JOIN AR_InvoiceDetail ON AR_InvoiceDetail.InvoiceHeaderID = AR_InvoiceHeader.InvoiceID AND AR_InvoiceDetail.CompanyID = AR_InvoiceHeader.CompanyID AND AR_InvoiceDetail.PeriodID = AR_InvoiceHeader.PeriodID where childPayment.PaymentID = payment.PaymentID and childPayment.CompanyID = payment.CompanyID and childPayment.PeriodID = payment.PeriodID ORDER BY AR_InvoiceHeader.InvoiceNumber FOR XML PATH(''), TYPE ).value('.', 'varchar(max)'), 1, 2, '') AS InvoiceNumbers FROM AP_PaymentHeader payment where payment.PaymentID = AP_PaymentHeader.PaymentID and payment.CompanyID = AP_PaymentHeader.CompanyID and payment.PeriodID = AP_PaymentHeader.PeriodID
), '')) else (Select DocumentNumber from AP_PurchaseOrderHeader where AP_PurchaseOrderHeader.POHeaderID = AP_PaymentHeader.POHeaderID and AP_PurchaseOrderHeader.CompanyID = AP_PaymentHeader.CompanyID and AP_PurchaseOrderHeader.PeriodID = AP_PaymentHeader.PeriodID ) end as InvoiceNumbers,
ISNULL( ( SELECT STUFF( ( SELECT ', ' + AP_PaymentDetail.InvoiceDocumentNo FROM AP_PaymentDetail WHERE payment1.PaymentID = AP_PaymentDetail.PaymentHeaderID ORDER BY AP_PaymentDetail.InvoiceDocumentNo FOR XML PATH(''), TYPE ).value('.', 'varchar(max)'), 1, 2, '') AS InvoiceDocumentNo FROM AP_PaymentHeader payment1 where payment1.PaymentID = AP_PaymentHeader.PaymentID and payment1.CompanyID = AP_PaymentHeader.CompanyID and payment1.PeriodID = AP_PaymentHeader.PeriodID ), '') as InvoiceDocumentNo, ISNULL(AP_PaymentHeader.DocumentNo, 0) AS DocumentNo, AP_PaymentHeader.DocumentDate AS DocumentDate, 0 AS FreightAmount , IsNull(AP_Payment_AccountsDetail.Amount, 0) * -1 As ForAlhajAmount FROM SET_DocumentType INNER JOIN AP_PaymentHeader ON SET_DocumentType.CompanyID = AP_PaymentHeader.CompanyID AND SET_DocumentType.PeriodID = AP_PaymentHeader.PeriodID AND SET_DocumentType.DocumentTypeID = AP_PaymentHeader.DocumentTypeID AND AP_PaymentHeader.Status = 1 AND AP_PaymentHeader.StatusCode = 1 INNER Join AP_PaymentSupplierDetail on AP_PaymentSupplierDetail.PaymentHeaderID = AP_PaymentHeader.PaymentID and AP_PaymentSupplierDetail.CompanyID = AP_PaymentHeader.CompanyID and AP_PaymentSupplierDetail.PeriodID = AP_PaymentHeader.PeriodID AND AP_PaymentSupplierDetail.Status=1 INNER JOIN AR_SET_Customer ON AP_PaymentSupplierDetail.SupplierID = AR_SET_Customer.CustomerID --AND AP_PaymentSupplierDetail.CompanyID = AR_SET_Customer.CompanyID AND AP_PaymentSupplierDetail.PeriodID = AR_SET_Customer.PeriodID AND AR_SET_Customer.Status = 1
--left JOin AP_PaymentBanksDetail on AP_PaymentBanksDetail.PaymentHeaderID=AP_PaymentHeader.PaymentID --AND AP_PaymentBanksDetail.CompanyID=AP_PaymentHeader.CompanyID --AND AP_PaymentBanksDetail.PeriodID=AP_PaymentHeader.PeriodID --AND AP_PaymentBanksDetail.Status=1 left join AP_Payment_AccountsDetail on AP_Payment_AccountsDetail.PaymentHeaderID = AP_PaymentHeader.PaymentID and AP_Payment_AccountsDetail.IsBP <> 0 and AP_Payment_AccountsDetail.TransactionType = 'Credit'
INNER JOIN AR_SET_BusinessPartnerTypes ON AR_SET_BusinessPartnerTypes.BusinessPartnerID = AR_SET_Customer.CustomerID --AND AR_SET_BusinessPartnerTypes.CompanyID = AR_SET_Customer.CompanyID AND AR_SET_BusinessPartnerTypes.PeriodID = AR_SET_Customer.PeriodID AND AR_SET_BusinessPartnerTypes.TypeCode = AP_PaymentSupplierDetail.BusinessPartnerTypeID LEFT JOIN SET_Department ON SET_Department.DepartmentID = AP_PaymentSupplierDetail.DepartmentID AND SET_Department.Status = 1 AND SET_Department.IsActive = 1 WHERE AP_PaymentHeader.CompanyID in @CompanyID AND AP_PaymentHeader.PeriodID = @PeriodId AND AP_PaymentHeader.DocumentDate < @FromDate And (SET_DocumentType.DocumentTypeID =@DocumentTypeiD Or @DocumentTypeiD is Null) AND (SET_Department.DepartmentID = @DepartmentID OR @DepartmentID IS NULL) {0} {1} {6} GROUP BY AP_PaymentHeader.CreateDate,AP_PaymentHeader.CompanyID, AR_SET_Customer.CustomerID, AR_SET_Customer.CustomerName, AP_PaymentSupplierDetail.PaymentSupplierID, AP_PaymentSupplierDetail.TransactionType, AP_PaymentSupplierDetail.Amount, AP_PaymentHeader.DocumentNo, AP_PaymentHeader.DocumentDate, SET_DocumentType.DocumentType, AP_PaymentHeader.PaymentID, AP_PaymentHeader.CompanyID, AP_PaymentHeader.PeriodID, AP_PaymentHeader.Comments, AP_PaymentHeader.POHeaderID, AP_Payment_AccountsDetail.Amount, AP_PaymentHeader.ReversalComments UNION ALL
-- PAYMENT -- SINGLE BUSINESS PARTNER CASE SELECT SET_DocumentType.DocumentType, AP_PaymentHeader.CreateDate, AP_PaymentHeader.CompanyID, AR_SET_Customer.CustomerID, AR_SET_Customer.CustomerName AS BusinessPartnerName, AP_PaymentHeader.PaymentID as SourceID, (Case when AP_PaymentHeader.CustomerTransactionType is not null then AP_PaymentHeader.Amount * -1 else AP_PaymentHeader.Amount end) - isnull(( select Sum(AP_PaymentSupplierDetail .Amount) as Amount from AP_PaymentSupplierDetail where AP_PaymentSupplierDetail.PaymentHeaderID = AP_PaymentHeader.PaymentID and AP_PaymentSupplierDetail.CompanyID = AP_PaymentHeader.CompanyID and AP_PaymentSupplierDetail.PeriodID = AP_PaymentHeader.PeriodID and AP_PaymentSupplierDetail.Status = 1 and AP_PaymentSupplierDetail.Narration = 'GST' ),0) as Amount, STUFF((SELECT ', ' + PBD.InstrumentNo FROM AP_PaymentBanksDetail PBD WHERE PBD.PaymentHeaderID = AP_PaymentHeader.PaymentID FOR XML PATH('')), 1, 1, '') AS InstrumentNo, AP_PaymentHeader.Comments + (Case When AP_PaymentHeader.ReversalComments IS NULL Then '' Else ' ' + AP_PaymentHeader.ReversalComments End) AS Comments, case when AP_PaymentHeader.POHeaderID is null then (ISNULL( ( SELECT STUFF( ( SELECT distinct AR_InvoiceHeader.InvoiceNumber FROM AP_PaymentHeader childPayment LEFT JOIN AP_PaymentInvoicesDetail ON AP_PaymentInvoicesDetail.PaymentHeaderID = childPayment.PaymentID AND AP_PaymentInvoicesDetail.CompanyID = childPayment.CompanyID AND AP_PaymentInvoicesDetail.PeriodID = childPayment.PeriodID LEFT JOIN AR_InvoiceHeader ON AR_InvoiceHeader.InvoiceID = AP_PaymentInvoicesDetail.InvoiceHeaderID AND AR_InvoiceHeader.CompanyID = AP_PaymentInvoicesDetail.CompanyID AND AR_InvoiceHeader.PeriodID = AP_PaymentInvoicesDetail.PeriodID LEFT JOIN AR_InvoiceDetail ON AR_InvoiceDetail.InvoiceHeaderID = AR_InvoiceHeader.InvoiceID AND AR_InvoiceDetail.CompanyID = AR_InvoiceHeader.CompanyID AND AR_InvoiceDetail.PeriodID = AR_InvoiceHeader.PeriodID where childPayment.PaymentID = payment.PaymentID and childPayment.CompanyID = payment.CompanyID and childPayment.PeriodID = payment.PeriodID ORDER BY AR_InvoiceHeader.InvoiceNumber FOR XML PATH(''), TYPE ).value('.', 'varchar(max)'), 1, 0, '') AS InvoiceNumbers FROM AP_PaymentHeader payment where payment.PaymentID = AP_PaymentHeader.PaymentID and payment.CompanyID = AP_PaymentHeader.CompanyID and payment.PeriodID = AP_PaymentHeader.PeriodID
), '')) else (Select DocumentNumber from AP_PurchaseOrderHeader where AP_PurchaseOrderHeader.POHeaderID = AP_PaymentHeader.POHeaderID and AP_PurchaseOrderHeader.CompanyID = AP_PaymentHeader.CompanyID and AP_PurchaseOrderHeader.PeriodID = AP_PaymentHeader.PeriodID ) end as InvoiceNumbers, ISNULL( ( SELECT STUFF( ( SELECT ', ' + AP_PaymentDetail.InvoiceDocumentNo FROM AP_PaymentDetail WHERE payment1.PaymentID = AP_PaymentDetail.PaymentHeaderID ORDER BY AP_PaymentDetail.InvoiceDocumentNo FOR XML PATH(''), TYPE ).value('.', 'varchar(max)'), 1, 2, '') AS InvoiceDocumentNo FROM AP_PaymentHeader payment1 where payment1.PaymentID = AP_PaymentHeader.PaymentID and payment1.CompanyID = AP_PaymentHeader.CompanyID and payment1.PeriodID = AP_PaymentHeader.PeriodID ), '') as InvoiceDocumentNo, ISNULL(AP_PaymentHeader.DocumentNo, 0) AS DocumentNo, AP_PaymentHeader.DocumentDate AS DocumentDate, 0 AS FreightAmount , IsNull(AP_Payment_AccountsDetail.Amount, 0) * -1 As ForAlhajAmount FROM SET_DocumentType INNER JOIN AP_PaymentHeader ON SET_DocumentType.CompanyID = AP_PaymentHeader.CompanyID AND SET_DocumentType.PeriodID = AP_PaymentHeader.PeriodID AND SET_DocumentType.DocumentTypeID = AP_PaymentHeader.DocumentTypeID AND AP_PaymentHeader.Status = 1 AND AP_PaymentHeader.StatusCode = 1 INNER JOIN AR_SET_Customer ON AP_PaymentHeader.VendorID = AR_SET_Customer.CustomerID --AND AP_PaymentHeader.CompanyID = AR_SET_Customer.CompanyID AND AP_PaymentHeader.PeriodID = AR_SET_Customer.PeriodID AND AR_SET_Customer.Status = 1
--left JOin AP_PaymentBanksDetail on AP_PaymentBanksDetail.PaymentHeaderID=AP_PaymentHeader.PaymentID -- AND AP_PaymentBanksDetail.CompanyID=AP_PaymentHeader.CompanyID -- AND AP_PaymentBanksDetail.PeriodID=AP_PaymentHeader.PeriodID -- AND AP_PaymentBanksDetail.Status=1
INNER JOIN AR_SET_BusinessPartnerTypes ON AR_SET_BusinessPartnerTypes.BusinessPartnerID = AR_SET_Customer.CustomerID --AND AR_SET_BusinessPartnerTypes.CompanyID = AR_SET_Customer.CompanyID AND AR_SET_BusinessPartnerTypes.PeriodID = AR_SET_Customer.PeriodID AND AR_SET_BusinessPartnerTypes.TypeCode = AP_PaymentHeader.BusinessPartnerTypeID INNER JOIN AR_SET_BusinessPartner ON AR_SET_BusinessPartner.BusinessPartnerID = AR_SET_BusinessPartnerTypes.TypeCode
left join AP_Payment_AccountsDetail on AP_Payment_AccountsDetail.PaymentHeaderID = AP_PaymentHeader.PaymentID and AP_Payment_AccountsDetail.IsBP <> 0 and AP_Payment_AccountsDetail.TransactionType = 'Credit' {7} WHERE AP_PaymentHeader.CompanyID in @CompanyID AND AP_PaymentHeader.PeriodID = @PeriodId AND AP_PaymentHeader.DocumentDate < @FromDate And (SET_DocumentType.DocumentTypeID =@DocumentTypeiD Or @DocumentTypeiD is Null) {0} {1} {6} GROUP BY AP_PaymentHeader.CreateDate,AP_PaymentHeader.CompanyID, AR_SET_Customer.CustomerID, AR_SET_Customer.CustomerName, AP_PaymentHeader.CustomerTransactionType, AP_PaymentHeader.Amount, AP_PaymentHeader.DocumentNo, AP_PaymentHeader.DocumentDate, SET_DocumentType.DocumentType, AP_PaymentHeader.PaymentID, AP_PaymentHeader.CompanyID, AP_PaymentHeader.PeriodID,AP_PaymentHeader.Comments, AP_PaymentHeader.POHeaderID ,AP_Payment_AccountsDetail.Amount, AP_PaymentHeader.ReversalComments UNION ALL -----------Sale Invoice Header----------- SELECT SET_DocumentType.DocumentType, SAL_InvoiceHeader.CreateDate, SAL_InvoiceHeader.CompanyID, AR_SET_Customer.CustomerID, AR_SET_Customer.CustomerName AS BusinessPartnerName, SAL_InvoiceHeader.InvoiceID as SourceID, case when SET_DocumentType.DocumentType = 'Credit Note' then SAL_InvoiceHeader.AmountPaid * -1 else SAL_InvoiceHeader.AmountPaid end as Amount, '0' AS InstrumentNo, '' AS Comments, '' as InvoiceNumbers, '' as InvoiceDocumentNo, ISNULL(SAL_InvoiceHeader.InvoiceNumber, 0) AS DocumentNo, SAL_InvoiceHeader.InvoiceDate AS DocumentDate, CASE WHEN GL_TransactionDetail.TransactionType = 'Debit' THEN ISNULL(SAL_InvoiceHeader.FreightAmount * -1, 0) else ISNULL(SAL_InvoiceHeader.FreightAmount, 0) end as FreightAmount , 0 As ForAlhajAmount FROM SET_DocumentType INNER JOIN SAL_InvoiceHeader ON SET_DocumentType.CompanyID = SAL_InvoiceHeader.CompanyID AND SET_DocumentType.PeriodID = SAL_InvoiceHeader.PeriodID AND SET_DocumentType.DocumentTypeID = SAL_InvoiceHeader.InvoiceType INNER JOIN AR_SET_Customer ON SAL_InvoiceHeader.CustomerID = AR_SET_Customer.CustomerID --AND SAL_InvoiceHeader.CompanyID = AR_SET_Customer.CompanyID AND SAL_InvoiceHeader.PeriodID = AR_SET_Customer.PeriodID AND SAL_InvoiceHeader.Status = 1 AND SAL_InvoiceHeader.StatusCode = 1 AND AR_SET_Customer.Status = 1 {1} INNER JOIN AR_SET_BusinessPartnerTypes ON AR_SET_BusinessPartnerTypes.BusinessPartnerID = AR_SET_Customer.CustomerID --AND AR_SET_BusinessPartnerTypes.CompanyID = AR_SET_Customer.CompanyID AND AR_SET_BusinessPartnerTypes.PeriodID = AR_SET_Customer.PeriodID
{0} INNER JOIN AR_SET_BusinessPartner ON AR_SET_BusinessPartner.BusinessPartnerID = AR_SET_BusinessPartnerTypes.TypeCode AND AR_SET_BusinessPartner.BusinessPartnerName = 'Customer' LEFT JOIN GL_TransactionDetail ON GL_TransactionDetail.CodeCombinationID = SAL_InvoiceHeader.FreightCode AND GL_TransactionDetail.SourceHeaderID = SAL_InvoiceHeader.InvoiceID AND GL_TransactionDetail.CompanyID = SAL_InvoiceHeader.CompanyID AND GL_TransactionDetail.PeriodID = SAL_InvoiceHeader.PeriodID {7} WHERE SAL_InvoiceHeader.CompanyID in @CompanyID and AR_SET_Customer.PeriodID = @PeriodID AND SAL_InvoiceHeader.InvoiceDate < @FromDate AND SAL_InvoiceHeader.InvoiceID NOT IN (SELECT InvoiceHeaderID FROM Sal_InvoiceCustomerDetail) And (SET_DocumentType.DocumentTypeID =@DocumentTypeiD Or @DocumentTypeiD is Null) {3} GROUP BY SAL_InvoiceHeader.CreateDate,SAL_InvoiceHeader.CompanyID, AR_SET_Customer.CustomerID, AR_SET_Customer.CustomerName, SAL_InvoiceHeader.InvoiceID, SAL_InvoiceHeader.AmountPaid, SAL_InvoiceHeader.InvoiceNumber, SAL_InvoiceHeader.InvoiceDate, SET_DocumentType.DocumentType, GL_TransactionDetail.TransactionType, SAL_InvoiceHeader.FreightAmount
UNION ALL
---------- Purchase Return ----------
select distinct FinTab.DocumentType, FinTab.CreateDate,CompanyID, FinTab.CustomerID, FinTab.BusinessPartnerName, FinTab.SourceID, FinTab.Amount, FinTab.InstrumentNo, FinTab.Comments, FinTab.InvoiceNumbers, FinTab.InvoiceDocumentNo, FinTab.DocumentNo, FinTab.DocumentDate, FinTab.FreightAmount, FinTab.ForAlhajAmount from ( Select distinct GL_TransactionHeader.DocumentDate,GL_TransactionHeader.CreateDate,GL_TransactionHeader.CompanyID, Set_DocumentType.DocumentType ,Set_DocumentType.DocumentTypeID, Set_CostCenter.CostCenterName, AR_Set_Customer.CustomerID, AR_Set_Customer.CustomerName as BusinessPartnerName, GL_TransactionHeader.DocumentNo, '' as DetailNarration, ' ' as Narration, '' as Comments, GL_TransactionDetail.CodeCombinationID as SupplierAccountCode, ( Case When GL_TransactionDetail.TransactionType = 'Debit' Then GL_TransactionDetail.Amount When GL_TransactionDetail.TransactionType = 'Credit' then GL_TransactionDetail.Amount * -1 Else 0 End ) as Amount, GL_codecombinationDetail.Description as CodeDescription ,'' AS InstrumentNo ,AR_InvoiceHeader.InvoiceNumber as InvoiceDocumentNo , 0 as FreightAmount , 0 As ForAlhajAmount ,AR_InvoiceHeader.VendorReferenceNumber as InvoiceNumbers ,STUFF(( select distinct ', ' + convert(varchar(10),INV_StockTransactionheader.DocumentNo) from INV_StockTransactionDetail inner join INV_StockTransactionheader on INV_StockTransactionheader.StockTransactionID = INV_StockTransactionDetail.StockTransactionID and INV_StockTransactionheader.CompanyID = INV_StockTransactionDetail.CompanyID and INV_StockTransactionheader.PeriodID = INV_StockTransactionDetail.PeriodID inner join AR_InvoiceDetail invDtl on invDtl.StockHeaderID = INV_StockTransactionDetail.StockTransactionID and invDtl.StockDetailID = INV_StockTransactionDetail.TransactionDetailID and invDtl.CompanyID = INV_StockTransactionDetail.CompanyID and invDtl.PeriodID = INV_StockTransactionDetail.PeriodID and invDtl.Status = 1 where INV_StockTransactionDetail.Status = 1 and invDtl.InvoiceHeaderID = AR_InvoiceDetail.InvoiceHeaderID and invDtl.CompanyID = AR_InvoiceDetail.CompanyID and invDtl.PeriodID = AR_InvoiceDetail.PeriodID FOR XML PATH('')), 1, 1, '') AS GRN_NO ,STUFF(( Select distinct ', ' + convert(varchar(10), AP_PurchaseOrderHeader.DocumentNumber) from AP_PurchaseOrderHeader left join AR_InvoiceDetail on AR_InvoiceDetail.PurchaseOrderHeaderID=AP_PurchaseOrderHeader.POHeaderID And AP_PurchaseOrderHeader.CompanyID=AR_InvoiceDetail.CompanyID And AP_PurchaseOrderHeader.PeriodID=AR_InvoiceDetail.PeriodID And AP_PurchaseOrderHeader.Status=1 Where AR_InvoiceDetail.InvoiceHeaderID=AR_InvoiceHeader.InvoiceID AND AR_InvoiceDetail.CompanyID=AR_InvoiceHeader.CompanyID And AR_InvoiceDetail.PeriodID=AR_InvoiceHeader.PeriodID AND AR_InvoiceDetail.Status=1
FOR XML PATH('')), 1, 1, '') AS PO_NO, '' AS SheetNo, '' AS FAX ,AR_SET_BusinessPartner.BusinessPartnerName as BPType ,INV_StockTransactionHeader.StockTransactionID as SourceID FROM INV_StockTransactionHeader INNER JOIN SET_DocumentType ON SET_DocumentType.CompanyID = INV_StockTransactionHeader.CompanyID AND SET_DocumentType.PeriodID = INV_StockTransactionHeader.PeriodID AND SET_DocumentType.DocumentTypeID = INV_StockTransactionHeader.DocumentTypeID and INV_StockTransactionHeader.status = 1
INNER JOIN AR_SET_Customer ON INV_StockTransactionHeader.BusinessPartnerID = AR_SET_Customer.CustomerID AND INV_StockTransactionHeader.PeriodID = AR_SET_Customer.PeriodID AND AR_SET_Customer.Status = 1
{1} inner join GL_TransactionHeader on GL_TransactionHeader.DocumentNo = INV_StockTransactionHeader.DocumentNo and GL_TransactionHeader.DocumentTypeID = SET_DocumentType.DocumentTypeID and INV_StockTransactionHeader.FiscalID = GL_TransactionHeader.FiscalID and GL_TransactionHeader.Status=1
INNER JOIN dbo.GL_TransactionDetail ON GL_TransactionHeader.TransactionID = GL_TransactionDetail.TransactionID AND GL_TransactionHeader.PeriodID = GL_TransactionDetail.PeriodID AND GL_TransactionHeader.CompanyID = GL_TransactionDetail.CompanyID AND GL_TransactionDetail.TransactionType = 'Debit' AND GL_TransactionDetail.Status=1 Inner JOIN AR_SET_BusinessPartnerTypes ON AR_SET_BusinessPartnerTypes.BusinessPartnerID = INV_StockTransactionHeader.BusinessPartnerID AND AR_SET_BusinessPartnerTypes.PeriodID = INV_StockTransactionHeader.PeriodID AND AR_SET_BusinessPartnerTypes.FK_CodeCombinationID = GL_TransactionDetail.CodeCombinationID {0} INNER JOIN AR_SET_BusinessPartner ON AR_SET_BusinessPartner.BusinessPartnerID = INV_StockTransactionHeader.BusinessPartnerTypeID {7}
Left Join Set_CostCenter On Set_CostCenter.CostCenterID = GL_TransactionDetail.CostCenterID inner join GL_codecombinationDetail on GL_codecombinationDetail.CodeCombinationID = GL_TransactionDetail.CodeCombinationID
----------------------
inner JOIN AR_InvoiceHeader ON SET_DocumentType.CompanyID = AR_InvoiceHeader.CompanyID AND SET_DocumentType.PeriodID = AR_InvoiceHeader.PeriodID AND AR_InvoiceHeader.Status = 1 AND AR_InvoiceHeader.StatusCode = 1 and AR_InvoiceHeader.InvoiceID = INV_StockTransactionHeader.InvoiceHeaderID LEFT JOIN AR_InvoiceDetail on AR_InvoiceDetail.CompanyID = AR_InvoiceHeader.CompanyID and AR_InvoiceDetail.PeriodID = AR_InvoiceHeader.PeriodID and AR_InvoiceDetail.InvoiceHeaderID = AR_InvoiceHeader.InvoiceID and AR_InvoiceDetail.Status=1 LEFT JOIN AR_InvoiceSupplierDetail on AR_InvoiceSupplierDetail.CompanyID = AR_InvoiceHeader.CompanyID and AR_InvoiceSupplierDetail.PeriodID = AR_InvoiceHeader.PeriodID and AR_InvoiceSupplierDetail.InvoiceHeaderID = AR_InvoiceHeader.InvoiceID and AR_InvoiceSupplierDetail.Status=1
----------------------
LEFT JOIN SET_Department ON SET_Department.DepartmentID = GL_TransactionDetail.DepartmentID AND SET_Department.Status = 1 AND SET_Department.IsActive = 1
WHERE INV_StockTransactionHeader.CompanyID in @CompanyID AND INV_StockTransactionHeader.PeriodID = @PeriodId AND INV_StockTransactionHeader.DocumentDate < @FromDate And (Set_DocumentType.DocumentTypeID = @DocumentTypeID Or @DocumentTypeID is null) and INV_StockTransactionHeader.BusinessPartnerTypeID is not null and INV_StockTransactionHeader.InvoiceHeaderID is not null AND (SET_Department.DepartmentID = @DepartmentID OR @DepartmentID IS NULL) --{3}
) As FinTab Group By FinTab.DocumentDate,CreateDate,CompanyID, FinTab.DocumentType,FinTab.DocumentTypeID, FinTab.CostCenterName , FinTab.CustomerID, FinTab.BusinessPartnerName, FinTab.DocumentNo, Fintab.Narration, FinTab.SupplierAccountCode, FinTab.CodeDescription,InstrumentNo,FinTab.InvoiceNumbers,GRN_NO,PO_NO,SheetNo,FAX, FinTab.SourceID,FinTab.Amount ,FinTab.DetailNarration,FinTab.InvoiceDocumentNo,FinTab.FreightAmount,FinTab.ForAlhajAmount,FinTab.BPType ,FinTab.Comments
UNION ALL
---------Import Document --------------- SELECT SET_DocumentType.DocumentType, AP_PurchaseOrderHeader.CreateDate, AP_PurchaseOrderHeader.CompanyID, AR_SET_Customer.CustomerID, AR_SET_Customer.CustomerName AS BusinessPartnerName, AP_PurchaseOrderHeader.POheaderID as SourceID, AP_PurchaseOrderHeader.TotalAmount * -1 as Amount, '0' AS InstrumentNo, '' AS Comments, '' as InvoiceNumbers, '' as InvoiceDocumentNo, ISNULL(AP_PurchaseOrderHeader.DocumentNumber, 0) AS DocumentNo, AP_PurchaseOrderHeader.DocumentDate AS DocumentDate, 0 as FreightAmount , 0 As ForAlhajAmount
FROM SET_DocumentType INNER JOIN AP_PurchaseOrderHeader ON SET_DocumentType.CompanyID = AP_PurchaseOrderHeader .CompanyID AND SET_DocumentType.PeriodID = AP_PurchaseOrderHeader .PeriodID AND SET_DocumentType.DocumentTypeID = AP_PurchaseOrderHeader.TypeCode and AP_PurchaseOrderHeader.status = 1
INNER JOIN AR_SET_Customer ON AP_PurchaseOrderHeader.VendorID = AR_SET_Customer.CustomerID AND AP_PurchaseOrderHeader.PeriodID = AR_SET_Customer.PeriodID AND AP_PurchaseOrderHeader.Status = 1 AND AP_PurchaseOrderHeader.StatusCode = 1 AND AR_SET_Customer.Status = 1 {1} INNER JOIN AR_SET_BusinessPartnerTypes ON AR_SET_BusinessPartnerTypes.BusinessPartnerID = AR_SET_Customer.CustomerID --AND AR_SET_BusinessPartnerTypes.CompanyID = AR_SET_Customer.CompanyID AND AR_SET_BusinessPartnerTypes.PeriodID = AR_SET_Customer.PeriodID {0}
INNER JOIN AR_SET_BusinessPartner ON AR_SET_BusinessPartner.BusinessPartnerID = AR_SET_BusinessPartnerTypes.TypeCode and AR_SET_BusinessPartner.BusinessPartnerName = 'International Vendor' {7} WHERE AP_PurchaseOrderHeader.CompanyID in @CompanyID and AR_SET_Customer.PeriodID = @PeriodID AND AP_PurchaseOrderHeader.DocumentDate < @FromDate And (SET_DocumentType.DocumentTypeID =@DocumentTypeiD Or @DocumentTypeiD is Null) and SET_DocumentType.DocumentType like '%import%' --{3}
UNION ALL
---------Custom Clearing --------------- SELECT SET_DocumentType.DocumentType, IMP_CustomClearing.CreateDate, IMP_CustomClearing.CompanyID, AR_SET_Customer.CustomerID, AR_SET_Customer.CustomerName AS BusinessPartnerName, IMP_CustomClearing.CustomClearingID as SourceID, IMP_CustomClearing.TotalInvoiceAmount * -1 as Amount, '0' AS InstrumentNo, '' AS Comments, '' as InvoiceNumbers, '' as InvoiceDocumentNo, ISNULL(IMP_CustomClearing.CustomClearingID, 0) AS DocumentNo, IMP_CustomClearing.CreateDate AS DocumentDate, 0 as FreightAmount , 0 As ForAlhajAmount FROM IMP_CustomClearing INNER JOIN SET_DocumentType ON SET_DocumentType.CompanyID = IMP_CustomClearing.CompanyID AND SET_DocumentType.PeriodID = IMP_CustomClearing.PeriodID AND SET_DocumentType.DocumentTypeID = (select top 1 DocumentTypeID from SET_DocumentType doctype where doctype.DocumentType = 'Custom Clearing' and doctype.CompanyID = IMP_CustomClearing.CompanyID ) and IMP_CustomClearing.status = 1
INNER JOIN AR_SET_Customer ON IMP_CustomClearing.ClearingAgentID = AR_SET_Customer.CustomerID AND IMP_CustomClearing.PeriodID = IMP_CustomClearing.PeriodID AND IMP_CustomClearing.Status = 1 AND AR_SET_Customer.Status = 1 {1} INNER JOIN AR_SET_BusinessPartnerTypes ON AR_SET_BusinessPartnerTypes.BusinessPartnerID = AR_SET_Customer.CustomerID --AND AR_SET_BusinessPartnerTypes.CompanyID = AR_SET_Customer.CompanyID AND AR_SET_BusinessPartnerTypes.PeriodID = AR_SET_Customer.PeriodID
{0} INNER JOIN AR_SET_BusinessPartner ON AR_SET_BusinessPartner.BusinessPartnerID = AR_SET_BusinessPartnerTypes.TypeCode and AR_SET_BusinessPartner.BusinessPartnerName = 'Service_Providers'
{7} WHERE IMP_CustomClearing.CompanyID in @CompanyID and AR_SET_Customer.PeriodID = @PeriodID AND IMP_CustomClearing.CreateDate < @FromDate And (SET_DocumentType.DocumentTypeID =@DocumentTypeiD Or @DocumentTypeiD is Null) --{3}
union all
---------Shipment Transportation --------------- SELECT SET_DocumentType.DocumentType, Set_ContainerTransportationandUnloading.CreateDate, Set_ContainerTransportationandUnloading.CompanyID, AR_SET_Customer.CustomerID, AR_SET_Customer.CustomerName AS BusinessPartnerName, Set_ContainerTransportationandUnloading.ContainerTransportationID as SourceID, Set_ContainerTransportationandUnloading.TotalTransAmount * -1 as Amount, '0' AS InstrumentNo, '' AS Comments, '' as InvoiceNumbers, '' as InvoiceDocumentNo, ISNULL(Set_ContainerTransportationandUnloading.ContainerTransportationID, 0) AS DocumentNo, Set_ContainerTransportationandUnloading.CreateDate AS DocumentDate, 0 as FreightAmount , 0 As ForAlhajAmount FROM Set_ContainerTransportationandUnloading INNER JOIN SET_DocumentType ON SET_DocumentType.CompanyID = Set_ContainerTransportationandUnloading.CompanyID AND SET_DocumentType.PeriodID = Set_ContainerTransportationandUnloading.PeriodID AND SET_DocumentType.DocumentTypeID = (select top 1 DocumentTypeID from SET_DocumentType doctype where doctype.DocumentType = 'Transportation' and doctype.CompanyID = Set_ContainerTransportationandUnloading.CompanyID ) and Set_ContainerTransportationandUnloading.status = 1
INNER JOIN AR_SET_Customer ON Set_ContainerTransportationandUnloading.TransporterID = AR_SET_Customer.CustomerID AND Set_ContainerTransportationandUnloading.PeriodID = Set_ContainerTransportationandUnloading.PeriodID AND Set_ContainerTransportationandUnloading.Status = 1 AND AR_SET_Customer.Status = 1 {1} INNER JOIN AR_SET_BusinessPartnerTypes ON AR_SET_BusinessPartnerTypes.BusinessPartnerID = AR_SET_Customer.CustomerID --AND AR_SET_BusinessPartnerTypes.CompanyID = AR_SET_Customer.CompanyID AND AR_SET_BusinessPartnerTypes.PeriodID = AR_SET_Customer.PeriodID {0} INNER JOIN AR_SET_BusinessPartner ON AR_SET_BusinessPartner.BusinessPartnerID = AR_SET_BusinessPartnerTypes.TypeCode and AR_SET_BusinessPartner.BusinessPartnerName = 'Vendor' {7} WHERE Set_ContainerTransportationandUnloading.CompanyID in @CompanyID and AR_SET_Customer.PeriodID = @PeriodID AND Set_ContainerTransportationandUnloading.CreateDate < @FromDate And (SET_DocumentType.DocumentTypeID =@DocumentTypeiD Or @DocumentTypeiD is Null) --{3}
union all
---------Direct LC Expense --------------- SELECT SET_DocumentType.DocumentType, DirectLcExpense_Header.CreateDate, DirectLcExpense_Header.CompanyID, AR_SET_Customer.CustomerID, AR_SET_Customer.CustomerName AS BusinessPartnerName, DirectLcExpense_Header.CustomClearingID as SourceID, DirectLcExpense_Header.TotalAmount * -1 as Amount, '0' AS InstrumentNo, '' AS Comments, '' as InvoiceNumbers, '' as InvoiceDocumentNo, ISNULL(DirectLcExpense_Header.CustomClearingID, 0) AS DocumentNo, DirectLcExpense_Header.CreateDate AS DocumentDate, 0 as FreightAmount , 0 As ForAlhajAmount FROM DirectLcExpense_Header INNER JOIN SET_DocumentType ON SET_DocumentType.CompanyID = DirectLcExpense_Header.CompanyID AND SET_DocumentType.PeriodID = DirectLcExpense_Header.PeriodID AND SET_DocumentType.DocumentTypeID = (select top 1 DocumentTypeID from SET_DocumentType doctype where doctype.DocumentType = 'LC Direct Expenses' and doctype.CompanyID = DirectLcExpense_Header.CompanyID ) and DirectLcExpense_Header.status = 1
INNER JOIN AR_SET_Customer ON DirectLcExpense_Header.ClearingAgentID = AR_SET_Customer.CustomerID AND DirectLcExpense_Header.PeriodID = DirectLcExpense_Header.PeriodID AND DirectLcExpense_Header.Status = 1 AND AR_SET_Customer.Status = 1 {1} INNER JOIN AR_SET_BusinessPartnerTypes ON AR_SET_BusinessPartnerTypes.BusinessPartnerID = AR_SET_Customer.CustomerID --AND AR_SET_BusinessPartnerTypes.CompanyID = AR_SET_Customer.CompanyID AND AR_SET_BusinessPartnerTypes.PeriodID = AR_SET_Customer.PeriodID {0} INNER JOIN AR_SET_BusinessPartner ON AR_SET_BusinessPartner.BusinessPartnerID = AR_SET_BusinessPartnerTypes.TypeCode and AR_SET_BusinessPartner.BusinessPartnerName = 'Vendor' {7} WHERE DirectLcExpense_Header.CompanyID in @CompanyID and AR_SET_Customer.PeriodID = @PeriodID AND DirectLcExpense_Header.CreateDate < @FromDate And (SET_DocumentType.DocumentTypeID =@DocumentTypeiD Or @DocumentTypeiD is Null) --{3}
union all
-----------Sale Invoice Header Detail Data----------- SELECT SET_DocumentType.DocumentType, SAL_InvoiceHeader.CreateDate, SAL_InvoiceHeader.CompanyID, AR_SET_Customer.CustomerID, AR_SET_Customer.CustomerName AS BusinessPartnerName, SAL_InvoiceHeader.InvoiceID as SourceID, (case when Sal_InvoiceCustomerDetail.TransactionType ='Credit' or SET_DocumentType.DocumentType = 'Credit Note' then SUM(Sal_InvoiceCustomerDetail.Amount *-1) else SUM(Sal_InvoiceCustomerDetail.Amount) end )Amount, '0' AS InstrumentNo, '' AS Comments, '' as InvoiceNumbers, '' as InvoiceDocumentNo, ISNULL(SAL_InvoiceHeader.InvoiceNumber, 0) AS DocumentNo, SAL_InvoiceHeader.InvoiceDate AS DocumentDate, CASE WHEN GL_TransactionDetail.TransactionType = 'Debit' THEN ISNULL(SAL_InvoiceHeader.FreightAmount * -1, 0) else ISNULL(SAL_InvoiceHeader.FreightAmount, 0) end as FreightAmount , 0 As ForAlhajAmount FROM SET_DocumentType INNER JOIN SAL_InvoiceHeader ON SET_DocumentType.CompanyID = SAL_InvoiceHeader.CompanyID AND SET_DocumentType.PeriodID = SAL_InvoiceHeader.PeriodID AND SET_DocumentType.DocumentTypeID = SAL_InvoiceHeader.InvoiceType inner join Sal_InvoiceCustomerDetail on Sal_InvoiceCustomerDetail.InvoiceHeaderID = SAL_InvoiceHeader.InvoiceID and Sal_InvoiceCustomerDetail.CompanyID = SAL_InvoiceHeader.CompanyID and Sal_InvoiceCustomerDetail.PeriodID = SAL_InvoiceHeader.PeriodID INNER JOIN AR_SET_Customer ON Sal_InvoiceCustomerDetail.CustomerID = AR_SET_Customer.CustomerID --AND Sal_InvoiceCustomerDetail.CompanyID = AR_SET_Customer.CompanyID AND Sal_InvoiceCustomerDetail.PeriodID = AR_SET_Customer.PeriodID AND SAL_InvoiceHeader.Status = 1 AND SAL_InvoiceHeader.StatusCode = 1 AND AR_SET_Customer.Status = 1 and Sal_InvoiceCustomerDetail.Status = 1
{1} INNER JOIN AR_SET_BusinessPartnerTypes ON AR_SET_BusinessPartnerTypes.BusinessPartnerID = AR_SET_Customer.CustomerID --AND AR_SET_BusinessPartnerTypes.CompanyID = AR_SET_Customer.CompanyID AND AR_SET_BusinessPartnerTypes.PeriodID = AR_SET_Customer.PeriodID AND AR_SET_BusinessPartnerTypes.TypeCode = Sal_InvoiceCustomerDetail.BusinessPartnerTypeID {0} inner JOIN AR_SET_BusinessPartner ON AR_SET_BusinessPartner.BusinessPartnerID = AR_SET_BusinessPartnerTypes.TypeCode LEFT JOIN GL_TransactionDetail ON GL_TransactionDetail.CodeCombinationID = SAL_InvoiceHeader.FreightCode AND GL_TransactionDetail.SourceHeaderID = SAL_InvoiceHeader.InvoiceID AND GL_TransactionDetail.CompanyID = SAL_InvoiceHeader.CompanyID AND GL_TransactionDetail.PeriodID = SAL_InvoiceHeader.PeriodID {7}
LEFT JOIN SET_Department ON SET_Department.DepartmentID = GL_TransactionDetail.DepartmentID AND SET_Department.Status = 1 AND SET_Department.IsActive = 1
WHERE SAL_InvoiceHeader.CompanyID in @CompanyID and AR_SET_Customer.PeriodID = @PeriodID AND SAL_InvoiceHeader.InvoiceDate < @FromDate And (SET_DocumentType.DocumentTypeID =@DocumentTypeiD Or @DocumentTypeiD is Null) AND (SET_Department.DepartmentID = @DepartmentID OR @DepartmentID IS NULL) {3} GROUP BY SAL_InvoiceHeader.CreateDate, SAL_InvoiceHeader.CompanyID, AR_SET_Customer.CustomerID, AR_SET_Customer.CustomerName, SAL_InvoiceHeader.InvoiceID, Sal_InvoiceCustomerDetail.Amount, SAL_InvoiceHeader.InvoiceNumber, SAL_InvoiceHeader.InvoiceDate, SET_DocumentType.DocumentType, GL_TransactionDetail.TransactionType, SAL_InvoiceHeader.FreightAmount ,Sal_InvoiceCustomerDetail.TransactionType
union all --RECEIPT TRANSACTION SELECT distinct SET_DocumentType.DocumentType, AR_ReceiptTransactionHeader.CreateDate, AR_ReceiptTransactionHeader.CompanyID, AR_SET_Customer.CustomerID, AR_SET_Customer.CustomerName AS BusinessPartnerName, AR_ReceiptTransactionHeader.ReceiptTransactionID as SourceID, Case when ( select Amount from AR_ReceiptAccountsDetail rad where rad.TransactionType = 'Credit' and rad.ReceiptHeaderID = AR_ReceiptAccountsDetail.ReceiptHeaderID and rad.ReceiptAccountID = AR_ReceiptAccountsDetail.ReceiptAccountID ) is null then AR_ReceiptTransactionHeader.Amount * -1 else AR_ReceiptTransactionHeader.Amount * -1 end as Amount, STUFF((SELECT ', ' + PBD.InstrumentNo FROM AR_ReceiptBanksDetail PBD WHERE PBD.ReceiptHeaderID = AR_ReceiptTransactionHeader.ReceiptTransactionID FOR XML PATH('')), 1, 1, '') AS InstrumentNo, IsNull(AR_ReceiptTransactionHeader.Comments, '') + (Case When AR_ReceiptTransactionHeader.ReversalComments IS NULL Then '' Else ' ' + AR_ReceiptTransactionHeader.ReversalComments End) AS Comments, STUFF((SELECT ', ' + SAL_InvoiceHeader.invoicenumber FROM AR_ReceiptInvoicesDetail PBD inner join SAL_InvoiceHeader on SAL_InvoiceHeader.InvoiceID = PBD.InvoiceHeaderID and SAL_InvoiceHeader.Status = 1 and SAL_InvoiceHeader.CompanyID = PBD.CompanyID and SAL_InvoiceHeader.PeriodID = PBD.PeriodID WHERE PBD.ReceiptHeaderID = AR_ReceiptTransactionHeader.ReceiptTransactionID and PBD.CompanyID = AR_ReceiptTransactionHeader.CompanyID --and PBD.PeriodID = AR_ReceiptTransactionHeader.PeriodID FOR XML PATH('')), 1, 1, '') AS InvoiceNumbers, '' as InvoiceDocumentNo, ISNULL(AR_ReceiptTransactionHeader.DocumentNo, 0) AS DocumentNo, AR_ReceiptTransactionHeader.DocumentDate AS DocumentDate, 0 AS FreightAmount, 0 As ForAlhajAmount FROM SET_DocumentType INNER JOIN AR_ReceiptTransactionHeader ON SET_DocumentType.CompanyID = AR_ReceiptTransactionHeader.CompanyID AND SET_DocumentType.PeriodID = AR_ReceiptTransactionHeader.PeriodID AND SET_DocumentType.DocumentTypeID = AR_ReceiptTransactionHeader.DocumentTypeID AND AR_ReceiptTransactionHeader.Status = 1 AND AR_ReceiptTransactionHeader.StatusCode = 1 -- Left Join AR_ReceiptBanksDetail on AR_ReceiptBanksDetail.ReceiptBankID=AR_ReceiptTransactionHeader.ReceiptTransactionID --AND AR_ReceiptBanksDetail.CompanyID=AR_ReceiptTransactionHeader.CompanyID --AND AR_ReceiptBanksDetail.PeriodID=AR_ReceiptTransactionHeader.PeriodID --AND AR_ReceiptBanksDetail.Status=1 INNER JOIN AR_SET_Customer ON AR_ReceiptTransactionHeader.CustomerID = AR_SET_Customer.CustomerID --AND AR_ReceiptTransactionHeader.CompanyID = AR_SET_Customer.CompanyID AND AR_ReceiptTransactionHeader.PeriodID = AR_SET_Customer.PeriodID AND AR_SET_Customer.Status = 1 {1} INNER JOIN AR_SET_BusinessPartnerTypes ON AR_SET_BusinessPartnerTypes.BusinessPartnerID = AR_SET_Customer.CustomerID --AND AR_SET_BusinessPartnerTypes.CompanyID = AR_SET_Customer.CompanyID AND AR_SET_BusinessPartnerTypes.PeriodID = AR_SET_Customer.PeriodID AND AR_SET_BusinessPartnerTypes.TypeCode = AR_ReceiptTransactionHeader.BusinessPartnerTypeID {0} INNER JOIN AR_SET_BusinessPartner ON AR_SET_BusinessPartner.BusinessPartnerID = AR_SET_BusinessPartnerTypes.TypeCode Left Join AR_ReceiptAccountsDetail on AR_ReceiptAccountsDetail.CompanyID = AR_ReceiptTransactionHeader.CompanyID AND AR_ReceiptAccountsDetail.PeriodID = AR_ReceiptTransactionHeader.PeriodID AND AR_ReceiptAccountsDetail.ReceiptHeaderID = AR_ReceiptTransactionHeader.ReceiptTransactionID {7} WHERE AR_ReceiptTransactionHeader.CompanyID in @CompanyID and AR_SET_Customer.PeriodID = @PeriodID AND AR_ReceiptTransactionHeader.DocumentDate < @FromDate And (SET_DocumentType.DocumentTypeID =@DocumentTypeiD Or @DocumentTypeiD is Null) and AR_ReceiptTransactionHeader.ReceiptTransactionID not in ( select ReceiptHeaderID from AR_ReceiptCustomerDetail inner join AR_ReceiptTransactionHeader RecHDR on RecHDR.ReceiptTransactionID = AR_ReceiptTransactionHeader.ReceiptTransactionID and RecHDR.CompanyID = AR_ReceiptTransactionHeader.CompanyID and RecHDR.PeriodID = AR_ReceiptTransactionHeader.PeriodID inner join set_documentType on set_documentType.DocumentTypeID = AR_ReceiptTransactionHeader.DocumentTypeID and set_documentType.CompanyID = AR_ReceiptTransactionHeader.CompanyID and set_documentType.PeriodID = AR_ReceiptTransactionHeader.PeriodID {7} where AR_ReceiptCustomerDetail.ReceiptHeaderID = AR_ReceiptTransactionHeader.ReceiptTransactionID and AR_ReceiptCustomerDetail.CompanyID = AR_ReceiptTransactionHeader.CompanyID and AR_ReceiptCustomerDetail.PeriodID = AR_ReceiptTransactionHeader.PeriodID and set_documentType.documentType not like '%Advance Against SO%' and set_documentType.documentType not like '%sale invoice%'
) {4} GROUP BY AR_ReceiptTransactionHeader.CreateDate,AR_ReceiptTransactionHeader.CompanyID, AR_SET_Customer.CustomerID, AR_SET_Customer.CustomerName, AR_ReceiptTransactionHeader.ReceiptTransactionID, AR_ReceiptAccountsDetail.ReceiptHeaderID, AR_ReceiptAccountsDetail.ReceiptAccountID,AR_ReceiptAccountsDetail.Amount, AR_ReceiptTransactionHeader.Amount, AR_ReceiptTransactionHeader.DocumentNo, AR_ReceiptTransactionHeader.DocumentDate, SET_DocumentType.DocumentType, AR_ReceiptTransactionHeader.Comments, ReversalComments ,AR_ReceiptTransactionHeader.ReceiptTransactionID
UNION ALL -- Receipt Transaction Without Opening SELECT SET_DocumentType.DocumentType, AR_ReceiptTransactionHeader.CreateDate, AR_ReceiptTransactionHeader.CompanyID, AR_SET_Customer.CustomerID, AR_SET_Customer.CustomerName AS BusinessPartnerName, AR_ReceiptTransactionHeader.ReceiptTransactionID as SourceID, Case when AR_ReceiptCustomerDetail.TransactionType = 'Debit' then AR_ReceiptCustomerDetail.Amount else AR_ReceiptCustomerDetail.Amount * -1 end as Amount, STUFF((SELECT ', ' + PBD.InstrumentNo FROM AR_ReceiptBanksDetail PBD WHERE PBD.ReceiptHeaderID = AR_ReceiptTransactionHeader.ReceiptTransactionID and PBD.CompanyID = AR_ReceiptTransactionHeader.CompanyID and PBD.PeriodID = AR_ReceiptTransactionHeader.PeriodID
FOR XML PATH('')), 1, 1, '') AS InstrumentNo, IsNull(AR_ReceiptTransactionHeader.Comments, '') + (Case When AR_ReceiptTransactionHeader.ReversalComments IS NULL Then '' Else ' ' + AR_ReceiptTransactionHeader.ReversalComments End) AS Comments, '' as InvoiceNumbers, '' as InvoiceDocumentNo, ISNULL(AR_ReceiptTransactionHeader.DocumentNo, 0) AS DocumentNo, AR_ReceiptTransactionHeader.DocumentDate, 0 AS FreightAmount, 0 As ForAlhajAmount FROM SET_DocumentType INNER JOIN AR_ReceiptTransactionHeader ON SET_DocumentType.CompanyID = AR_ReceiptTransactionHeader.CompanyID AND SET_DocumentType.PeriodID = AR_ReceiptTransactionHeader.PeriodID AND SET_DocumentType.DocumentTypeID = AR_ReceiptTransactionHeader.DocumentTypeID AND AR_ReceiptTransactionHeader.Status = 1 AND AR_ReceiptTransactionHeader.StatusCode = 1 -- Left Join AR_ReceiptBanksDetail on AR_ReceiptBanksDetail.ReceiptHeaderID = AR_ReceiptTransactionHeader.ReceiptTransactionID --AND AR_ReceiptBanksDetail.CompanyID= AR_ReceiptTransactionHeader.CompanyID --AND AR_ReceiptBanksDetail.PeriodID = AR_ReceiptTransactionHeader.PeriodID --AND AR_ReceiptBanksDetail.Status=1 INNER JOIN AR_ReceiptCustomerDetail on AR_ReceiptCustomerDetail.ReceiptHeaderID = AR_ReceiptTransactionHeader.ReceiptTransactionID and AR_ReceiptCustomerDetail.CompanyID = AR_ReceiptTransactionHeader.CompanyID and AR_ReceiptCustomerDetail.PeriodID = AR_ReceiptTransactionHeader.PeriodID and AR_ReceiptCustomerDetail.status = 1 INNER JOIN AR_SET_Customer ON AR_ReceiptCustomerDetail.CustomerID = AR_SET_Customer.CustomerID --AND AR_ReceiptCustomerDetail.CompanyID = AR_SET_Customer.CompanyID AND AR_ReceiptCustomerDetail.PeriodID = AR_SET_Customer.PeriodID AND AR_SET_Customer.Status = 1 {1} INNER JOIN AR_SET_BusinessPartnerTypes ON AR_SET_BusinessPartnerTypes.BusinessPartnerID = AR_SET_Customer.CustomerID --AND AR_SET_BusinessPartnerTypes.CompanyID = AR_SET_Customer.CompanyID AND AR_SET_BusinessPartnerTypes.PeriodID = AR_SET_Customer.PeriodID AND AR_SET_BusinessPartnerTypes.TypeCode = AR_ReceiptCustomerDetail.BusinessPartnerTypeID {0} INNER JOIN AR_SET_BusinessPartner ON AR_SET_BusinessPartner.BusinessPartnerID = AR_SET_BusinessPartnerTypes.TypeCode LEFT Join AR_ReceiptAccountsDetail on AR_ReceiptAccountsDetail.CompanyID = AR_ReceiptTransactionHeader.CompanyID AND AR_ReceiptAccountsDetail.PeriodID = AR_ReceiptTransactionHeader.PeriodID AND AR_ReceiptAccountsDetail.ReceiptHeaderID = AR_ReceiptTransactionHeader.ReceiptTransactionID {7} WHERE AR_ReceiptTransactionHeader.CompanyID in @CompanyID and AR_SET_Customer.PeriodID = @PeriodID AND AR_ReceiptTransactionHeader.DocumentDate < @FromDate and SET_DocumentType.DocumentType not like '%opening%' And (SET_DocumentType.DocumentTypeID =@DocumentTypeiD Or @DocumentTypeiD is Null) {4} GROUP BY AR_ReceiptTransactionHeader.CreateDate,AR_ReceiptTransactionHeader.CompanyID, AR_SET_Customer.CustomerID, AR_SET_Customer.CustomerName, AR_ReceiptCustomerDetail.ReceiptCustomerID, AR_ReceiptCustomerDetail.TransactionType, AR_ReceiptCustomerDetail.Amount, AR_ReceiptTransactionHeader.Amount, AR_ReceiptTransactionHeader.DocumentNo, AR_ReceiptTransactionHeader.DocumentDate, SET_DocumentType.DocumentType, AR_ReceiptTransactionHeader.Comments, AR_ReceiptTransactionHeader.ReversalComments,AR_ReceiptTransactionHeader.ReceiptTransactionID,AR_ReceiptTransactionHeader.CompanyID,AR_ReceiptTransactionHeader.PeriodID
UNION ALL -- Receipt Transaction [Only Opening]
SELECT Distinct SET_DocumentType.DocumentType, AR_ReceiptTransactionHeader.CreateDate, AR_ReceiptTransactionHeader.CompanyID, AR_SET_Customer.CustomerID, AR_SET_Customer.CustomerName AS BusinessPartnerName, AR_ReceiptCustomerDetail.ReceiptCustomerID as SourceID, Case when AR_ReceiptCustomerDetail.TransactionType = 'Debit' then AR_ReceiptCustomerDetail.Amount else AR_ReceiptCustomerDetail.Amount * -1 end as Amount, STUFF((SELECT ', ' + PBD.InstrumentNo FROM AR_ReceiptBanksDetail PBD WHERE PBD.ReceiptHeaderID = AR_ReceiptTransactionHeader.ReceiptTransactionID FOR XML PATH('')), 1, 1, '') AS InstrumentNo, IsNull(AR_ReceiptTransactionHeader.Comments, '') + (Case When AR_ReceiptTransactionHeader.ReversalComments IS NULL Then '' Else ' ' + AR_ReceiptTransactionHeader.ReversalComments End) AS Comments, '' as InvoiceNumbers, '' as InvoiceDocumentNo, ISNULL(AR_ReceiptTransactionHeader.DocumentNo, 0) AS DocumentNo, AR_ReceiptTransactionHeader.DocumentDate, 0 AS FreightAmount, 0 As ForAlhajAmount FROM SET_DocumentType INNER JOIN AR_ReceiptTransactionHeader ON SET_DocumentType.CompanyID = AR_ReceiptTransactionHeader.CompanyID AND SET_DocumentType.PeriodID = AR_ReceiptTransactionHeader.PeriodID AND SET_DocumentType.DocumentTypeID = AR_ReceiptTransactionHeader.DocumentTypeID AND AR_ReceiptTransactionHeader.Status = 1 AND AR_ReceiptTransactionHeader.StatusCode = 1 -- Left Join AR_ReceiptBanksDetail on AR_ReceiptBanksDetail.ReceiptHeaderID = AR_ReceiptTransactionHeader.ReceiptTransactionID --AND AR_ReceiptBanksDetail.CompanyID= AR_ReceiptTransactionHeader.CompanyID --AND AR_ReceiptBanksDetail.PeriodID = AR_ReceiptTransactionHeader.PeriodID --AND AR_ReceiptBanksDetail.Status=1 INNER JOIN AR_ReceiptCustomerDetail on AR_ReceiptCustomerDetail.ReceiptHeaderID = AR_ReceiptTransactionHeader.ReceiptTransactionID and AR_ReceiptCustomerDetail.CompanyID = AR_ReceiptTransactionHeader.CompanyID and AR_ReceiptCustomerDetail.PeriodID = AR_ReceiptTransactionHeader.PeriodID and AR_ReceiptCustomerDetail.status = 1 INNER JOIN AR_SET_Customer ON AR_ReceiptCustomerDetail.CustomerID = AR_SET_Customer.CustomerID --AND AR_ReceiptCustomerDetail.CompanyID = AR_SET_Customer.CompanyID AND AR_ReceiptCustomerDetail.PeriodID = AR_SET_Customer.PeriodID AND AR_SET_Customer.Status = 1 {1} INNER JOIN AR_SET_BusinessPartnerTypes ON AR_SET_BusinessPartnerTypes.BusinessPartnerID = AR_SET_Customer.CustomerID --AND AR_SET_BusinessPartnerTypes.CompanyID = AR_SET_Customer.CompanyID AND AR_SET_BusinessPartnerTypes.PeriodID = AR_SET_Customer.PeriodID AND AR_SET_BusinessPartnerTypes.TypeCode = AR_ReceiptCustomerDetail.BusinessPartnerTypeID {0} INNER JOIN AR_SET_BusinessPartner ON AR_SET_BusinessPartner.BusinessPartnerID = AR_SET_BusinessPartnerTypes.TypeCode LEFT Join AR_ReceiptAccountsDetail on AR_ReceiptAccountsDetail.CompanyID = AR_ReceiptTransactionHeader.CompanyID AND AR_ReceiptAccountsDetail.PeriodID = AR_ReceiptTransactionHeader.PeriodID AND AR_ReceiptAccountsDetail.ReceiptHeaderID = AR_ReceiptTransactionHeader.ReceiptTransactionID {7} WHERE AR_ReceiptTransactionHeader.CompanyID in @CompanyID and AR_SET_Customer.PeriodID = @PeriodID AND AR_ReceiptTransactionHeader.DocumentDate < @FromDate And (SET_DocumentType.DocumentTypeID =@DocumentTypeiD Or @DocumentTypeiD is Null) and SET_DocumentType.DocumentType like '%opening%' {4} GROUP BY AR_ReceiptTransactionHeader.CreateDate,AR_ReceiptTransactionHeader.CompanyID, AR_SET_Customer.CustomerID, AR_SET_Customer.CustomerName, AR_ReceiptCustomerDetail.ReceiptCustomerID, AR_ReceiptCustomerDetail.TransactionType, AR_ReceiptCustomerDetail.Amount, AR_ReceiptTransactionHeader.Amount, AR_ReceiptTransactionHeader.DocumentNo, AR_ReceiptTransactionHeader.DocumentDate, SET_DocumentType.DocumentType, AR_ReceiptTransactionHeader.Comments, AR_ReceiptTransactionHeader.ReversalComments,AR_ReceiptTransactionHeader.ReceiptTransactionID
UNION ALL -- Commission On Receipt SELECT Distinct SET_DocumentType.DocumentType, AR_ReceiptTransactionHeader.CreateDate, AR_ReceiptTransactionHeader.CompanyID, AR_SET_Customer.CustomerID, AR_SET_Customer.CustomerName AS BusinessPartnerName, AR_ReceiptTransactionHeader.ReceiptTransactionID as SourceID, ((AR_ReceiptTransactionHeader.Amount * AR_ReceiptTransactionHeader.CommissionPercentage)/100) * -1 as Amount, STUFF((SELECT ', ' + PBD.InstrumentNo FROM AR_ReceiptBanksDetail PBD WHERE PBD.ReceiptHeaderID = AR_ReceiptTransactionHeader.ReceiptTransactionID FOR XML PATH('')), 1, 1, '') AS InstrumentNo, IsNull(AR_ReceiptTransactionHeader.Comments, '') + (Case When AR_ReceiptTransactionHeader.ReversalComments IS NULL Then '' Else ' ' + AR_ReceiptTransactionHeader.ReversalComments End) AS Comments, '' as InvoiceNumbers, '' as InvoiceDocumentNo, ISNULL(AR_ReceiptTransactionHeader.DocumentNo, 0) AS DocumentNo, AR_ReceiptTransactionHeader.DocumentDate AS DocumentDate, 0 AS FreightAmount, 0 As ForAlhajAmount FROM SET_DocumentType INNER JOIN AR_ReceiptTransactionHeader ON SET_DocumentType.CompanyID = AR_ReceiptTransactionHeader.CompanyID AND SET_DocumentType.PeriodID = AR_ReceiptTransactionHeader.PeriodID AND SET_DocumentType.DocumentTypeID = AR_ReceiptTransactionHeader.DocumentTypeID AND AR_ReceiptTransactionHeader.Status = 1 AND AR_ReceiptTransactionHeader.StatusCode = 1 -- Left Join AR_ReceiptBanksDetail on AR_ReceiptBanksDetail.ReceiptHeaderID = AR_ReceiptTransactionHeader.ReceiptTransactionID --AND AR_ReceiptBanksDetail.CompanyID= AR_ReceiptTransactionHeader.CompanyID --AND AR_ReceiptBanksDetail.PeriodID = AR_ReceiptTransactionHeader.PeriodID --AND AR_ReceiptBanksDetail.Status=1
INNER JOIN AR_SET_Customer ON AR_ReceiptTransactionHeader.EmployeeID = AR_SET_Customer.CustomerID --AND AR_ReceiptTransactionHeader.CompanyID = AR_SET_Customer.CompanyID AND AR_ReceiptTransactionHeader.PeriodID = AR_SET_Customer.PeriodID AND AR_SET_Customer.Status = 1 {1} INNER JOIN AR_SET_BusinessPartnerTypes ON AR_SET_BusinessPartnerTypes.BusinessPartnerID = AR_SET_Customer.CustomerID --AND AR_SET_BusinessPartnerTypes.CompanyID = AR_SET_Customer.CompanyID AND AR_SET_BusinessPartnerTypes.PeriodID = AR_SET_Customer.PeriodID AND AR_SET_BusinessPartnerTypes.TypeCode = AR_ReceiptTransactionHeader.BusinessPartnerTypeID {0} INNER JOIN AR_SET_BusinessPartner ON AR_SET_BusinessPartner.BusinessPartnerID = AR_SET_BusinessPartnerTypes.TypeCode Left Join AR_ReceiptAccountsDetail on AR_ReceiptAccountsDetail.CompanyID = AR_ReceiptTransactionHeader.CompanyID AND AR_ReceiptAccountsDetail.PeriodID = AR_ReceiptTransactionHeader.PeriodID AND AR_ReceiptAccountsDetail.ReceiptHeaderID = AR_ReceiptTransactionHeader.ReceiptTransactionID {7} WHERE AR_ReceiptTransactionHeader.CompanyID in @CompanyID and AR_SET_Customer.PeriodID = @PeriodID AND AR_ReceiptTransactionHeader.DocumentDate < @FromDate And (SET_DocumentType.DocumentTypeID =@DocumentTypeiD Or @DocumentTypeiD is Null) {4} GROUP BY AR_ReceiptTransactionHeader.CreateDate,AR_ReceiptTransactionHeader.CompanyID, AR_SET_Customer.CustomerID, AR_SET_Customer.CustomerName, AR_ReceiptTransactionHeader.ReceiptTransactionID, AR_ReceiptTransactionHeader.CommissionPercentage, AR_ReceiptAccountsDetail.ReceiptHeaderID, AR_ReceiptAccountsDetail.ReceiptAccountID,AR_ReceiptAccountsDetail.Amount, AR_ReceiptTransactionHeader.Amount, AR_ReceiptTransactionHeader.DocumentNo, AR_ReceiptTransactionHeader.DocumentDate, SET_DocumentType.DocumentType, AR_ReceiptTransactionHeader.Comments, ReversalComments, AR_ReceiptTransactionHeader.ReceiptTransactionID
-------- SALE DISCOUNT -----------
union All SELECT distinct SET_DocumentType.DocumentType, SAL_DiscountTransactionHeader.CreateDate, SAL_DiscountTransactionHeader.CompanyID, AR_SET_Customer.CustomerID, AR_SET_Customer.CustomerName AS BusinessPartnerName, SAL_DiscountTransactionHeader.DiscountTransactionHeaderID as SourceID, (SAL_DiscountTransactionHeader.CalculatedAmount * -1) as Amount, '0' AS InstrumentNo, '' AS Comments, '' as InvoiceNumbers, '' as InvoiceDocumentNo, ISNULL(SAL_DiscountTransactionHeader.DiscountTransactionHeaderID, 0) AS DocumentNo, SAL_DiscountTransactionHeader.RunDateTime AS DocumentDate, 0 AS FreightAmount, 0 As ForAlhajAmount FROM SET_DocumentType INNER JOIN SAL_DiscountTransactionHeader ON SET_DocumentType.CompanyID = SAL_DiscountTransactionHeader.CompanyID AND SET_DocumentType.PeriodID = SAL_DiscountTransactionHeader.PeriodID AND SET_DocumentType.DocumentTypeID = SAL_DiscountTransactionHeader.DocumentTypeID INNER JOIN AR_SET_Customer ON SAL_DiscountTransactionHeader.CustomerID = AR_SET_Customer.CustomerID --AND SAL_DiscountTransactionHeader.CompanyID = AR_SET_Customer.CompanyID AND SAL_DiscountTransactionHeader.PeriodID = AR_SET_Customer.PeriodID AND AR_SET_Customer.Status = 1 {1} INNER JOIN AR_SET_BusinessPartnerTypes ON AR_SET_BusinessPartnerTypes.BusinessPartnerID = AR_SET_Customer.CustomerID --AND AR_SET_BusinessPartnerTypes.CompanyID = AR_SET_Customer.CompanyID AND AR_SET_BusinessPartnerTypes.PeriodID = AR_SET_Customer.PeriodID {0} INNER JOIN AR_SET_BusinessPartner ON AR_SET_BusinessPartner.BusinessPartnerID = AR_SET_BusinessPartnerTypes.TypeCode {7} WHERE SAL_DiscountTransactionHeader.CompanyID in @CompanyID and AR_SET_Customer.PeriodID = @PeriodID AND SAL_DiscountTransactionHeader.RunDateTime < @FromDate And (SET_DocumentType.DocumentTypeID =@DocumentTypeiD Or @DocumentTypeiD is Null)
UNION ALL
----Sales Invoice Return SELECT SET_DocumentType.DocumentType, SAL_ReverseHeader.CreateDate, SAL_ReverseHeader.CompanyID, AR_SET_Customer.CustomerID, AR_SET_Customer.CustomerName AS Name, SAL_ReverseHeader.ReverseHeaderID as SourceID, --case when SET_DocumentType.DocumentType = 'Credit Note' then SUM(ABS(SAL_ReverseDetail.ReversedAmount * -1)) else --SUM(ABS(SAL_ReverseDetail.ReversedAmount* -1)) end as Amount, SUM(SAL_ReverseDetail.ReversedAmount) * -1 as Amount, '' AS InstrumentNo, GL_TransactionHeader.Narration AS Comments, SAL_InvoiceHeader.InvoiceNumber as InvoiceNumbers, SAL_InvoiceHeader.InvoiceNumber as InvoiceDocumentNo, ISNULL(SAL_ReverseHeader.DocumentNo, 0) AS DocumentNo, SAL_ReverseHeader.CreateDate AS DocumentDate, 0 as FreightAmount , 0 As ForAlhajAmount
FROM SET_DocumentType Inner join SAL_ReverseHeader on SAL_ReverseHeader.CompanyID= SET_DocumentType.CompanyID and SAL_ReverseHeader.PeriodID = SET_DocumentType.PeriodID and SAL_ReverseHeader.DocumentTypeID = SET_DocumentType.DocumentTypeID and SAL_ReverseHeader.Status = 1 and SET_DocumentType.Status = 1
inner join SAL_ReverseDetail on SAL_ReverseDetail.ReverseHeaderID = SAL_ReverseHeader.ReverseHeaderID and SAL_ReverseHeader.CompanyID= SAL_ReverseDetail.CompanyID and SAL_ReverseHeader.PeriodID = SAL_ReverseDetail.PeriodID and SAL_ReverseDetail.Status = 1
inner join SAL_InvoiceDetail on SAL_InvoiceDetail.InvoiceDetailID = SAL_ReverseDetail.SourceDetailID and SAL_InvoiceDetail.InvoiceHeaderID = SAL_ReverseDetail.SourceHeaderID and SAL_InvoiceDetail.CompanyID = SAL_ReverseDetail.CompanyID and SAL_InvoiceDetail.Status = 1
inner join SAL_InvoiceHeader on SAL_InvoiceHeader.InvoiceID =SAL_InvoiceDetail.InvoiceHeaderID and SAL_InvoiceHeader.InvoiceNumber = SAL_ReverseDetail.SourceCode and SAL_InvoiceHeader.InvoiceType = SAL_ReverseDetail.SourceDocumentTypeID and SAL_InvoiceHeader.status = 1 and SAL_InvoiceHeader.CompanyID = SAL_ReverseDetail.CompanyID and SAL_InvoiceHeader.CompanyID = SAL_InvoiceDetail.CompanyID
left join GL_TransactionHeader on GL_TransactionHeader.DocumentNo = SAL_ReverseHeader.DocumentNo and GL_TransactionHeader.DocumentTypeID = SAL_ReverseHeader.DocumentTypeID and GL_TransactionHeader.CompanyID = SAL_ReverseHeader.CompanyID and GL_TransactionHeader.PeriodID = SAL_ReverseHeader.PeriodID and GL_TransactionHeader.FiscalID = SAL_ReverseHeader.FiscalID and GL_TransactionHeader.Status = 1
INNER JOIN AR_SET_Customer ON SAL_InvoiceHeader.CustomerID = AR_SET_Customer.CustomerID AND SAL_InvoiceHeader.CompanyID = AR_SET_Customer.CompanyID AND SAL_InvoiceHeader.PeriodID = AR_SET_Customer.PeriodID AND SAL_InvoiceHeader.Status = 1 AND SAL_InvoiceHeader.StatusCode = 1 AND AR_SET_Customer.Status = 1 AND AR_SET_Customer.IsActive = 1 {1} INNER JOIN AR_SET_BusinessPartnerTypes ON AR_SET_BusinessPartnerTypes.BusinessPartnerID = AR_SET_Customer.CustomerID AND AR_SET_BusinessPartnerTypes.CompanyID = AR_SET_Customer.CompanyID AND AR_SET_BusinessPartnerTypes.PeriodID = AR_SET_Customer.PeriodID {0} INNER JOIN AR_SET_BusinessPartner ON AR_SET_BusinessPartner.BusinessPartnerID = AR_SET_BusinessPartnerTypes.TypeCode AND AR_SET_BusinessPartner.BusinessPartnerName = 'Local Sale Debtor - Sugar'
{7} WHERE SAL_ReverseHeader.CompanyID in @CompanyID AND SAL_ReverseHeader.PeriodID = @PeriodID AND SAL_ReverseHeader.CreateDate < @FromDate and SAL_ReverseHeader.StatusCode = 1 {3} GROUP BY SAL_InvoiceHeader.CreateDate, AR_SET_Customer.CustomerID, AR_SET_Customer.CustomerName,AR_SET_Customer.ContactNumber , AR_SET_Customer.ContactPerson , AR_SET_Customer.AddressLine1,SAL_ReverseHeader.CreateDate,SAL_ReverseHeader.ReverseHeaderID, SET_DocumentType.DocumentType ,SAL_ReverseHeader.DocumentNo ,SAL_ReverseHeader.CompanyID,SAL_InvoiceHeader.InvoiceNumber,GL_TransactionHeader.Narration
union all
-- Invoice Discount
SELECT distinct SET_DocumentType.DocumentType, AR_InvoiceHeader.CreateDate, AR_InvoiceHeader.CompanyID, AR_SET_Customer.CustomerID, AR_SET_Customer.CustomerName AS BusinessPartnerName, AR_InvoiceHeader.InvoiceID as SourceID, sum(isnull(AR_InvoiceDetail.DiscountAmountTaken,0)) as Amount, '0' AS InstrumentNo, '' AS Comments, AR_InvoiceHeader.VendorReferenceNumber as InvoiceNumbers, '' as InvoiceDocumentNo, ISNULL(AR_InvoiceHeader.InvoiceNumber, 0) AS DocumentNo, AR_InvoiceHeader.InvoiceDate AS DocumentDate, 0 AS FreightAmount, 0 As ForAlhajAmount
FROM AR_InvoiceHeader inner join AR_InvoiceDetail on AR_InvoiceDetail.InvoiceHeaderID = AR_InvoiceHeader.InvoiceID and AR_InvoiceDetail.CompanyID = AR_InvoiceHeader.CompanyID and AR_InvoiceDetail.PeriodID = AR_InvoiceHeader.PeriodID INNER JOIN SET_DocumentType ON AR_InvoiceHeader.InvoiceType = SET_DocumentType.DocumentTypeID and AR_InvoiceHeader.CompanyID = SET_DocumentType.CompanyID INNER JOIN AR_SET_Customer ON AR_SET_Customer.CustomerID = AR_InvoiceHeader.VendorID AND AR_SET_Customer.Status = 1 {1}
left JOIN AR_SET_BusinessPartnerTypes ON AR_SET_BusinessPartnerTypes.BusinessPartnerID = AR_InvoiceHeader.VendorID AND AR_SET_BusinessPartnerTypes.PeriodID = AR_InvoiceHeader.PeriodID AND AR_SET_BusinessPartnerTypes.TypeCode = AR_InvoiceHeader.BusinessPartnerTypeID LEFT JOIN AR_SET_BusinessPartner ON AR_SET_BusinessPartner.BusinessPartnerID = AR_SET_BusinessPartnerTypes.TypeCode
WHERE AR_InvoiceHeader.CompanyID in @CompanyID AND AR_InvoiceHeader.PeriodID = @PeriodId AND AR_InvoiceHeader.InvoiceDate < @FromDate {0} {5} group by SET_DocumentType.DocumentType, AR_InvoiceHeader.CreateDate , AR_InvoiceHeader.CompanyID,AR_SET_Customer.CustomerID, AR_SET_Customer.CustomerName ,AR_InvoiceHeader.InvoiceID,AR_InvoiceHeader.InvoiceNumber,AR_InvoiceHeader.InvoiceDate,AR_SET_BusinessPartner.BusinessPartnerName ,AR_InvoiceDetail.InvoiceHeaderID,AR_InvoiceDetail.CompanyID,AR_InvoiceDetail.PeriodID,AR_InvoiceHeader.PeriodID ,AR_InvoiceHeader.VendorReferenceNumber
) AS FINTAB GROUP BY DocumentType, CreateDate,CompanyID, CustomerID, NAME, SourceID, InstrumentNo, Comments, InvoiceNumbers, InvoiceDocumentNo, DocumentNo, DocumentDate, FreightAmount, ForAlhajAmount ) as TABopening -- For Transation type Filter {2} GROUP BY TABopening.CustomerID,CompanyID, TABopening.Name--,TABopening.Comments
UNION ALL
select * from ( SELECT FINTAB.DocumentType, Fintab.CreateDate,CompanyID, FINTAB.CustomerID, FINTAB.Name, FinTab.SourceID, SUM(FINTAB.Amount) as Amount, FINTAB.InstrumentNo, FINTAB.Comments, FINTAB.DetailNarration, FINTAB.InvoiceNumbers, FINTAB.InvoiceDocumentNo, FINTAB.DocumentNo, FINTAB.DocumentDate, FINTAB.FreightAmount, FINTAB.ForAlhajAmount ,FINTAB.BPType,FINTAB.GRN_NO,FINTAB.PO_NO,FINTAB.SheetNo,FINTAB.FAX FROM ( Select 'Opening' as DocumentType, @FromDate AS CreateDate,0 as CompanyID, OpeningTAB.CustomerID, openingTAB.Name, -1 AS SourceID, sum(openingTAB.Amount) as Amount, '' as InstrumentNo, '' as Comments,'' as DetailNarration ,'' as InvoiceNumbers, '' as InvoiceDocumentNo, '' as DocumentNo, @FromDate as DocumentDate, 0 AS FreightAmount, 0 As ForAlhajAmount ,'' as BPType,'' as GRN_NO,'' as PO_NO, '' AS SheetNo, '' AS FAX From ( SELECT 0 as Amount, 0 AS CustomerID, '' AS Name, 0 as SourceID , STUFF((SELECT ', ' + PBD.InstrumentNo FROM AR_ReceiptBanksDetail PBD WHERE PBD.ReceiptHeaderID = AR_ReceiptTransactionHeader.ReceiptTransactionID FOR XML PATH('')), 1, 1, '') AS InstrumentNo FROM SET_DocumentType INNER JOIN AR_ReceiptTransactionHeader ON SET_DocumentType.CompanyID = AR_ReceiptTransactionHeader.CompanyID AND SET_DocumentType.PeriodID = AR_ReceiptTransactionHeader.PeriodID AND SET_DocumentType.DocumentTypeID = AR_ReceiptTransactionHeader.DocumentTypeID AND AR_ReceiptTransactionHeader.Status = 1 AND AR_ReceiptTransactionHeader.StatusCode = 1 INNER JOIN AR_ReceiptCustomerDetail on AR_ReceiptCustomerDetail.ReceiptHeaderID = AR_ReceiptTransactionHeader.ReceiptTransactionID and AR_ReceiptCustomerDetail.CompanyID = AR_ReceiptTransactionHeader.CompanyID and AR_ReceiptCustomerDetail.PeriodID = AR_ReceiptTransactionHeader.PeriodID and AR_ReceiptCustomerDetail.status = 1 INNER JOIN AR_SET_Customer ON AR_ReceiptCustomerDetail.CustomerID = AR_SET_Customer.CustomerID --AND AR_ReceiptCustomerDetail.CompanyID = AR_SET_Customer.CompanyID AND AR_ReceiptCustomerDetail.PeriodID = AR_SET_Customer.PeriodID AND AR_SET_Customer.Status = 1
-- Left Join AR_ReceiptBanksDetail on AR_ReceiptBanksDetail.ReceiptHeaderID = AR_ReceiptTransactionHeader.ReceiptTransactionID --AND AR_ReceiptBanksDetail.CompanyID= AR_ReceiptTransactionHeader.CompanyID --AND AR_ReceiptBanksDetail.PeriodID = AR_ReceiptTransactionHeader.PeriodID --AND AR_ReceiptBanksDetail.Status=1
INNER JOIN AR_SET_BusinessPartnerTypes ON AR_SET_BusinessPartnerTypes.BusinessPartnerID = AR_SET_Customer.CustomerID --AND AR_SET_BusinessPartnerTypes.CompanyID = AR_SET_Customer.CompanyID AND AR_SET_BusinessPartnerTypes.PeriodID = AR_SET_Customer.PeriodID AND AR_SET_BusinessPartnerTypes.TypeCode = AR_ReceiptCustomerDetail.BusinessPartnerTypeID INNER JOIN AR_SET_BusinessPartner ON AR_SET_BusinessPartner.BusinessPartnerID = AR_SET_BusinessPartnerTypes.TypeCode LEFT Join AR_ReceiptAccountsDetail on AR_ReceiptAccountsDetail.CompanyID = AR_ReceiptTransactionHeader.CompanyID AND AR_ReceiptAccountsDetail.PeriodID = AR_ReceiptTransactionHeader.PeriodID AND AR_ReceiptAccountsDetail.ReceiptHeaderID = AR_ReceiptTransactionHeader.ReceiptTransactionID {7} WHERE AR_ReceiptTransactionHeader.CompanyID in @CompanyID and AR_SET_Customer.PeriodID = @PeriodID AND AR_ReceiptTransactionHeader.DocumentDate < @FromDate And (SET_DocumentType.DocumentTypeID =@DocumentTypeiD Or @DocumentTypeiD is Null) {0} {1} {4} GROUP BY AR_SET_Customer.CustomerID, AR_SET_Customer.CustomerName, AR_ReceiptCustomerDetail.TransactionType, AR_ReceiptCustomerDetail.ReceiptCustomerID,AR_ReceiptTransactionHeader.ReceiptTransactionID ) OpeningTAB GROUP BY OpeningTAB.CustomerID, OpeningTAB.Name
UNION ALL
select distinct TABInvoice.DocumentType, TABInvoice.CreateDate,CompanyID, TABInvoice.CustomerID, TABInvoice.BusinessPartnerName, TABInvoice.SourceID, TABInvoice.Amount, TABInvoice.InstrumentNo, TABInvoice.Comments,TABInvoice.DetailNarration , TABInvoice.InvoiceNumbers, TABInvoice.InvoiceDocumentNo, TABInvoice.DocumentNo, TABInvoice.DocumentDate, TABInvoice.FreightAmount, TABInvoice.ForAlhajAmount ,TABInvoice.BPType,GRN_NO,PO_NO,SheetNo,FAX from ( ---------- Vendor Invoice ---------- SELECT distinct AR_InvoiceHeader.companyID, Set_DocumentType.TransactionType, case when AR_SET_BusinessPartnerTypes.TypeCode is null then ( select top 1 CUS.TypeCode from AR_SET_BusinessPartnerTypes CUS where AR_InvoiceSupplierDetail.SupplierID = CUS.BusinessPartnerID AND AR_InvoiceSupplierDetail.CompanyID = CUS.CompanyID AND AR_InvoiceSupplierDetail.PeriodID = CUS.PeriodID ) else AR_SET_BusinessPartnerTypes.TypeCode end as TypeCode, case when AR_InvoiceHeader.vendorID is null then ( select CUS.CustomerID from AR_SET_Customer CUS where AR_InvoiceSupplierDetail.SupplierID = CUS.CustomerID --AND AR_InvoiceSupplierDetail.CompanyID = CUS.CompanyID AND AR_InvoiceSupplierDetail.PeriodID = CUS.PeriodID ) else ( select CUS.CustomerID from AR_SET_Customer CUS where AR_InvoiceHeader.vendorID = CUS.CustomerID --AND AR_InvoiceHeader.CompanyID = CUS.CompanyID AND AR_InvoiceHeader.PeriodID = CUS.PeriodID ) end as CustomerID, SET_DocumentType.DocumentType, AR_InvoiceHeader.CreateDate, case when AR_InvoiceHeader.vendorID is null then ( select CUS.CustomerName from AR_SET_Customer CUS where AR_InvoiceSupplierDetail.SupplierID = CUS.CustomerID --AND AR_InvoiceSupplierDetail.CompanyID = CUS.CompanyID AND AR_InvoiceSupplierDetail.PeriodID = CUS.PeriodID ) else ( select CUS.CustomerName from AR_SET_Customer CUS where AR_InvoiceHeader.vendorID = CUS.CustomerID --AND AR_InvoiceHeader.CompanyID = CUS.CompanyID AND AR_InvoiceHeader.PeriodID = CUS.PeriodID ) end as BusinessPartnerName, -- AR_InvoiceSupplierDetail.InvoiceSupplierID as SourceID, CASE WHEN AR_InvoiceHeader.vendorID is null then AR_InvoiceSupplierDetail.InvoiceSupplierID else AR_InvoiceHeader.InvoiceID end as SourceID, --case when AR_InvoiceHeader.vendorID is null then -- (Case when AR_InvoiceSupplierDetail.TransactionType = 'Debit' then AR_InvoiceSupplierDetail.Amount else AR_InvoiceSupplierDetail.Amount * -1 end) -- else -- ( -- Case when AR_InvoiceSupplierDetail.TransactionType = 'Debit' then AR_InvoiceHeader.AmountPaid -- when SET_DocumentType.DocumentType = 'Debit Note' then AR_InvoiceHeader.AmountPaid -- else (Isnull(AR_InvoiceHeader.AmountPaid,0) + Isnull(AR_InvoiceHeader.FreightAmount,0) - ISnull(AR_InvoiceHeader.OtherAmount,0)) * -1 end -- ) end as Amount, case when AR_InvoiceHeader.vendorID is null then (Case when AR_InvoiceSupplierDetail.TransactionType = 'Debit' then AR_InvoiceSupplierDetail.Amount else AR_InvoiceSupplierDetail.Amount * -1 end) else ( Case when AR_InvoiceSupplierDetail.TransactionType = 'Debit' AND AR_InvoiceHeader.vendorID is null then AR_InvoiceHeader.AmountPaid when SET_DocumentType.DocumentType = 'Debit Note' then AR_InvoiceHeader.AmountPaid --else (AR_InvoiceHeader.AmountPaid + AR_InvoiceHeader.FreightAmount - isnull(AR_InvoiceHeader.OtherAmount,0)) * -1 end else ( select case when (select count(*) from SET_Parameter where FieldName = 'MergeTaxes') = 0 then sum(GrossAmount) else sum(NetAmount) end from AR_InvoiceDetail invdtl where invdtl.InvoiceHeaderID = AR_InvoiceHeader.InvoiceID and invdtl.CompanyID = AR_InvoiceHeader.CompanyID and invdtl.PeriodID = AR_InvoiceHeader.PeriodID and invdtl.Status = 1
) * -1 end
