) end as Amount, '0' AS InstrumentNo, '' AS Comments, '' as DetailNarration, '' as InvoiceNumbers, '' as InvoiceDocumentNo, ISNULL(SAL_InvoiceHeader.InvoiceNumber, 0) AS DocumentNo, SAL_InvoiceHeader.InvoiceDate AS DocumentDate, CASE WHEN GL_TransactionDetail.TransactionType = 'Debit' THEN ISNULL(SAL_InvoiceHeader.FreightAmount * -1, 0) else ISNULL(SAL_InvoiceHeader.FreightAmount, 0) end as FreightAmount , 0 As ForAlhajAmount ,AR_SET_BusinessPartner.BusinessPartnerName as BPType ,STUFF(( select distinct ', ' + convert(varchar(10),INV_StockTransactionHeader.DocumentNo) from SAL_InvoiceHeader invHdr inner join SAL_InvoiceDetail invdtl on invdtl.InvoiceHeaderID = invHdr.InvoiceID and invdtl.CompanyID = invHdr.CompanyID and invdtl.PeriodID = invHdr.PeriodID inner join INV_StockTransactionDetail stkdtl on stkdtl.StockTransactionID = invdtl.StockHeaderID and stkdtl.TransactionDetailID = invdtl.StockDetailID and stkdtl.CompanyID = invdtl.CompanyID and stkdtl.PeriodID = invdtl.PeriodID and stkdtl.Status = 1
inner join INV_StockTransactionHeader on INV_StockTransactionHeader.StockTransactionID = stkdtl.StockTransactionID and INV_StockTransactionHeader.CompanyID = stkdtl.CompanyID and INV_StockTransactionHeader.PeriodID = stkdtl.PeriodID
where invHdr.InvoiceID = SAL_InvoiceHeader.InvoiceID and invHdr.CompanyID = SAL_InvoiceHeader.CompanyID and invHdr.PeriodID = SAL_InvoiceHeader.PeriodID FOR XML PATH('')), 1, 1, '') AS GRN_NO
,STUFF(( select distinct ', ' + convert(varchar(10),isnull(SAL_ContractHeader.ContractNo ,SAL_OrderHeader.ContractNo)) from SAL_InvoiceHeader invHdr inner join SAL_InvoiceDetail invdtl on invdtl.InvoiceHeaderID = invHdr.InvoiceID and invdtl.CompanyID = invHdr.CompanyID and invdtl.PeriodID = invHdr.PeriodID inner join INV_StockTransactionDetail stkdtl on stkdtl.StockTransactionID = invdtl.StockHeaderID and stkdtl.TransactionDetailID = invdtl.StockDetailID and stkdtl.CompanyID = invdtl.CompanyID and stkdtl.PeriodID = invdtl.PeriodID and stkdtl.Status = 1 inner join SAL_DeliveryOrderHeader delOrder on delOrder.DeliveryOrderID = stkdtl.SourceHeaderID and delOrder.DeliveryOrderNo = stkdtl.SourceCode and delOrder.DocumentTypeID = stkdtl.SourceDocumentTypeID and delOrder.CompanyID = stkdtl.CompanyID and delOrder.status = 1 inner join SAL_DeliveryOrderDetail doDtl on doDtl.DOHeaderID = delOrder.DeliveryOrderID and doDtl.CompanyID = delOrder.CompanyID and doDtl.PeriodID = delOrder.PeriodID and doDtl.Status = 1 left join SAL_OrderDetail on SAL_OrderDetail.OrderID = doDtl.SalesOrderHeaderID and SAL_OrderDetail.OrderDetailID = doDtl.SalesOrderDetailID and SAL_OrderDetail.CompanyID = doDtl.CompanyID and SAL_OrderDetail.PeriodID = doDtl.PeriodID and SAL_OrderDetail.Status = 1 left join SAL_OrderHeader on SAL_OrderHeader.orderID = SAL_OrderDetail.OrderID and SAL_OrderHeader.CompanyID = SAL_OrderDetail.CompanyID and SAL_OrderHeader.PeriodID = SAL_OrderDetail.PeriodID
left join SAL_ContractDetail on SAL_ContractDetail.ContractDetailID = SAL_OrderDetail.ContractDetailID and SAL_ContractDetail.ContractID = SAL_OrderDetail.ContractHeaderID and SAL_ContractDetail.CompanyID =SAL_OrderDetail.CompanyID and SAL_ContractDetail.PeriodID =SAL_OrderDetail.PeriodID and SAL_ContractDetail.ItemID =SAL_OrderDetail.ItemID and SAL_ContractDetail.Status = 1
left join SAL_ContractHeader on SAL_ContractHeader.ContractID = SAL_ContractDetail.ContractID and SAL_ContractHeader.CompanyID = SAL_ContractDetail.CompanyID and SAL_ContractHeader.PeriodID = SAL_ContractDetail.PeriodID
where invHdr.InvoiceID = SAL_InvoiceHeader.InvoiceID and invHdr.CompanyID = SAL_InvoiceHeader.CompanyID and invHdr.PeriodID = SAL_InvoiceHeader.PeriodID FOR XML PATH('')), 1, 1, '') AS PO_NO, '' AS SheetNo, '' AS FAX FROM SET_DocumentType INNER JOIN SAL_InvoiceHeader ON SET_DocumentType.CompanyID = SAL_InvoiceHeader.CompanyID AND SET_DocumentType.PeriodID = SAL_InvoiceHeader.PeriodID AND SET_DocumentType.DocumentTypeID = SAL_InvoiceHeader.InvoiceType INNER JOIN AR_SET_Customer ON SAL_InvoiceHeader.CustomerID = AR_SET_Customer.CustomerID --AND SAL_InvoiceHeader.CompanyID = AR_SET_Customer.CompanyID AND SAL_InvoiceHeader.PeriodID = AR_SET_Customer.PeriodID AND SAL_InvoiceHeader.Status = 1 AND SAL_InvoiceHeader.StatusCode = 1 AND AR_SET_Customer.Status = 1 {1} INNER JOIN AR_SET_BusinessPartnerTypes ON AR_SET_BusinessPartnerTypes.BusinessPartnerID = AR_SET_Customer.CustomerID --AND AR_SET_BusinessPartnerTypes.CompanyID = AR_SET_Customer.CompanyID AND AR_SET_BusinessPartnerTypes.PeriodID = AR_SET_Customer.PeriodID
{0} INNER JOIN AR_SET_BusinessPartner ON AR_SET_BusinessPartner.BusinessPartnerID = AR_SET_BusinessPartnerTypes.TypeCode AND AR_SET_BusinessPartner.BusinessPartnerName = 'Customer' left Join GL_TransactionHeader On Sal_InvoiceHeader.CompanyID = GL_TransactionHeader.CompanyID And Sal_InvoiceHeader.PeriodID = GL_TransactionHeader.PeriodID And Sal_InvoiceHeader.InvoiceType = GL_TransactionHeader.DocumentTypeID And Sal_InvoiceHeader.InvoiceNumber = GL_TransactionHeader.DocumentNo And Sal_InvoiceHeader.Status = 1 And Sal_InvoiceHeader.StatusCode = 1 and Sal_InvoiceHeader.FiscalID = GL_TransactionHeader.FiscalID Inner Join GL_TransactionDetail On GL_TransactionDetail.CompanyID = GL_TransactionHeader.CompanyID And GL_TransactionDetail.PeriodID = GL_TransactionHeader.PeriodID And GL_TransactionDetail.TransactionID = GL_TransactionHeader.TransactionID And GL_TransactionDetail.Status = 1 And GL_TransactionDetail.TransactionType = 'Debit' LEFT JOIN SET_Department ON SET_Department.DepartmentID = GL_TransactionDetail.DepartmentID AND SET_Department.Status = 1 AND SET_Department.IsActive = 1 {7} WHERE SAL_InvoiceHeader.CompanyID in @CompanyID and AR_SET_Customer.PeriodID = @PeriodID AND SAL_InvoiceHeader.InvoiceDate BETWEEN @FromDate AND @ToDate AND SAL_InvoiceHeader.InvoiceID NOT IN (SELECT InvoiceHeaderID FROM Sal_InvoiceCustomerDetail where Sal_InvoiceCustomerDetail.companyID = SAL_InvoiceHeader.CompanyID and Sal_InvoiceCustomerDetail.status = 1) And (SET_DocumentType.DocumentTypeID =@DocumentTypeiD Or @DocumentTypeiD is Null) AND (SET_Department.DepartmentID = @DepartmentID OR @DepartmentID IS NULL) {3} GROUP BY SAL_InvoiceHeader.CreateDate,SAL_InvoiceHeader.CompanyID, AR_SET_Customer.CustomerID, AR_SET_Customer.CustomerName, SAL_InvoiceHeader.InvoiceID, SAL_InvoiceHeader.AmountPaid, SAL_InvoiceHeader.InvoiceNumber, SAL_InvoiceHeader.InvoiceDate, SET_DocumentType.DocumentType, GL_TransactionDetail.TransactionType, SAL_InvoiceHeader.FreightAmount ,AR_SET_BusinessPartner.BusinessPartnerName,SAL_InvoiceHeader.PeriodID ,GL_TransactionHeader.TransactionID,GL_TransactionHeader.CompanyID,GL_TransactionHeader.FiscalID
UNION ALL
---------Import Document --------------- SELECT SET_DocumentType.DocumentType, AP_PurchaseOrderHeader.CreateDate, AP_PurchaseOrderHeader.CompanyID, AR_SET_Customer.CustomerID, AR_SET_Customer.CustomerName AS BusinessPartnerName, AP_PurchaseOrderHeader.POheaderID as SourceID, AP_PurchaseOrderHeader.TotalAmount * -1 as Amount, '0' AS InstrumentNo, '' AS Comments, '' as DetailNarration, '' as InvoiceNumbers, '' as InvoiceDocumentNo, ISNULL(AP_PurchaseOrderHeader.DocumentNumber, 0) AS DocumentNo, AP_PurchaseOrderHeader.DocumentDate AS DocumentDate, 0 as FreightAmount , 0 As ForAlhajAmount ,AR_SET_BusinessPartner.BusinessPartnerName as BPType ,'' as GRN_NO,'' as PO_NO, '' AS SheetNo, '' AS FAX FROM SET_DocumentType INNER JOIN AP_PurchaseOrderHeader ON SET_DocumentType.CompanyID = AP_PurchaseOrderHeader .CompanyID AND SET_DocumentType.PeriodID = AP_PurchaseOrderHeader .PeriodID AND SET_DocumentType.DocumentTypeID = AP_PurchaseOrderHeader.TypeCode and AP_PurchaseOrderHeader.status = 1
INNER JOIN AR_SET_Customer ON AP_PurchaseOrderHeader.VendorID = AR_SET_Customer.CustomerID AND AP_PurchaseOrderHeader.PeriodID = AR_SET_Customer.PeriodID AND AP_PurchaseOrderHeader.Status = 1 AND AP_PurchaseOrderHeader.StatusCode = 1 AND AR_SET_Customer.Status = 1 {1} INNER JOIN AR_SET_BusinessPartnerTypes ON AR_SET_BusinessPartnerTypes.BusinessPartnerID = AR_SET_Customer.CustomerID --AND AR_SET_BusinessPartnerTypes.CompanyID = AR_SET_Customer.CompanyID AND AR_SET_BusinessPartnerTypes.PeriodID = AR_SET_Customer.PeriodID {0}
INNER JOIN AR_SET_BusinessPartner ON AR_SET_BusinessPartner.BusinessPartnerID = AR_SET_BusinessPartnerTypes.TypeCode and AR_SET_BusinessPartner.BusinessPartnerName = 'International Vendor' {7} WHERE AP_PurchaseOrderHeader.CompanyID in @CompanyID and AR_SET_Customer.PeriodID = @PeriodID AND AP_PurchaseOrderHeader.DocumentDate BETWEEN @FromDate AND @ToDate And (SET_DocumentType.DocumentTypeID =@DocumentTypeiD Or @DocumentTypeiD is Null) and SET_DocumentType.DocumentType like '%import%' --{3}
UNION ALL
---------Custom Clearing --------------- SELECT SET_DocumentType.DocumentType, IMP_CustomClearing.CreateDate, IMP_CustomClearing.CompanyID, AR_SET_Customer.CustomerID, AR_SET_Customer.CustomerName AS BusinessPartnerName, IMP_CustomClearing.CustomClearingID as SourceID, IMP_CustomClearing.TotalInvoiceAmount * -1 as Amount, '0' AS InstrumentNo, '' AS Comments, '' as DetailNarration, '' as InvoiceNumbers, '' as InvoiceDocumentNo, ISNULL(IMP_CustomClearing.CustomClearingID, 0) AS DocumentNo, IMP_CustomClearing.CreateDate AS DocumentDate, 0 as FreightAmount , 0 As ForAlhajAmount ,AR_SET_BusinessPartner.BusinessPartnerName as BPType ,'' as GRN_NO,'' as PO_NO, '' AS SheetNo, '' AS FAX FROM IMP_CustomClearing INNER JOIN SET_DocumentType ON SET_DocumentType.CompanyID = IMP_CustomClearing.CompanyID AND SET_DocumentType.PeriodID = IMP_CustomClearing.PeriodID AND SET_DocumentType.DocumentTypeID = (select top 1 DocumentTypeID from SET_DocumentType doctype where doctype.DocumentType = 'Custom Clearing' and doctype.CompanyID = IMP_CustomClearing.CompanyID ) and IMP_CustomClearing.status = 1
INNER JOIN AR_SET_Customer ON IMP_CustomClearing.ClearingAgentID = AR_SET_Customer.CustomerID AND IMP_CustomClearing.PeriodID = IMP_CustomClearing.PeriodID AND IMP_CustomClearing.Status = 1 AND AR_SET_Customer.Status = 1 {1} INNER JOIN AR_SET_BusinessPartnerTypes ON AR_SET_BusinessPartnerTypes.BusinessPartnerID = AR_SET_Customer.CustomerID --AND AR_SET_BusinessPartnerTypes.CompanyID = AR_SET_Customer.CompanyID AND AR_SET_BusinessPartnerTypes.PeriodID = AR_SET_Customer.PeriodID {0}
INNER JOIN AR_SET_BusinessPartner ON AR_SET_BusinessPartner.BusinessPartnerID = AR_SET_BusinessPartnerTypes.TypeCode and AR_SET_BusinessPartner.BusinessPartnerName = 'Service_Providers' {7}
WHERE IMP_CustomClearing.CompanyID in @CompanyID and AR_SET_Customer.PeriodID = @PeriodID AND IMP_CustomClearing.CreateDate BETWEEN @FromDate AND @ToDate And (SET_DocumentType.DocumentTypeID =@DocumentTypeiD Or @DocumentTypeiD is Null) --{3} union all
---------Shipment Transportation --------------- SELECT SET_DocumentType.DocumentType, Set_ContainerTransportationandUnloading.CreateDate, Set_ContainerTransportationandUnloading.CompanyID, AR_SET_Customer.CustomerID, AR_SET_Customer.CustomerName AS BusinessPartnerName, Set_ContainerTransportationandUnloading.ContainerTransportationID as SourceID, Set_ContainerTransportationandUnloading.TotalTransAmount * -1 as Amount, '0' AS InstrumentNo, '' AS Comments, '' as DetailNarration, '' as InvoiceNumbers, '' as InvoiceDocumentNo, ISNULL(Set_ContainerTransportationandUnloading.ContainerTransportationID, 0) AS DocumentNo, Set_ContainerTransportationandUnloading.CreateDate AS DocumentDate, 0 as FreightAmount , 0 As ForAlhajAmount ,AR_SET_BusinessPartner.BusinessPartnerName as BPType ,'' as GRN_NO,'' as PO_NO, '' AS SheetNo, '' AS FAX FROM Set_ContainerTransportationandUnloading INNER JOIN SET_DocumentType ON SET_DocumentType.CompanyID = Set_ContainerTransportationandUnloading.CompanyID AND SET_DocumentType.PeriodID = Set_ContainerTransportationandUnloading.PeriodID AND SET_DocumentType.DocumentTypeID = (select top 1 DocumentTypeID from SET_DocumentType doctype where doctype.DocumentType = 'Transportation' and doctype.CompanyID = Set_ContainerTransportationandUnloading.CompanyID ) and Set_ContainerTransportationandUnloading.status = 1
INNER JOIN AR_SET_Customer ON Set_ContainerTransportationandUnloading.TransporterID = AR_SET_Customer.CustomerID AND Set_ContainerTransportationandUnloading.PeriodID = Set_ContainerTransportationandUnloading.PeriodID AND Set_ContainerTransportationandUnloading.Status = 1 AND AR_SET_Customer.Status = 1 {1} INNER JOIN AR_SET_BusinessPartnerTypes ON AR_SET_BusinessPartnerTypes.BusinessPartnerID = AR_SET_Customer.CustomerID --AND AR_SET_BusinessPartnerTypes.CompanyID = AR_SET_Customer.CompanyID AND AR_SET_BusinessPartnerTypes.PeriodID = AR_SET_Customer.PeriodID {0} INNER JOIN AR_SET_BusinessPartner ON AR_SET_BusinessPartner.BusinessPartnerID = AR_SET_BusinessPartnerTypes.TypeCode and AR_SET_BusinessPartner.BusinessPartnerName = 'Vendor' {7} WHERE Set_ContainerTransportationandUnloading.CompanyID in @CompanyID and AR_SET_Customer.PeriodID = @PeriodID AND Set_ContainerTransportationandUnloading.CreateDate BETWEEN @FromDate AND @ToDate And (SET_DocumentType.DocumentTypeID =@DocumentTypeiD Or @DocumentTypeiD is Null) --{3}
