---------Direct LC Expense --------------- SELECT SET_DocumentType.DocumentType, DirectLcExpense_Header.CreateDate, DirectLcExpense_Header.CompanyID, AR_SET_Customer.CustomerID, AR_SET_Customer.CustomerName AS BusinessPartnerName, DirectLcExpense_Header.CustomClearingID as SourceID, DirectLcExpense_Header.TotalAmount * -1 as Amount, '0' AS InstrumentNo, '' AS Comments, '' as DetailNarration, '' as InvoiceNumbers, '' as InvoiceDocumentNo, ISNULL(DirectLcExpense_Header.CustomClearingID, 0) AS DocumentNo, DirectLcExpense_Header.CreateDate AS DocumentDate, 0 as FreightAmount , 0 As ForAlhajAmount ,AR_SET_BusinessPartner.BusinessPartnerName as BPType ,'' as GRN_NO,'' as PO_NO, '' AS SheetNo, '' AS FAX FROM DirectLcExpense_Header INNER JOIN SET_DocumentType ON SET_DocumentType.CompanyID = DirectLcExpense_Header.CompanyID AND SET_DocumentType.PeriodID = DirectLcExpense_Header.PeriodID AND SET_DocumentType.DocumentTypeID = (select top 1 DocumentTypeID from SET_DocumentType doctype where doctype.DocumentType = 'LC Direct Expenses' and doctype.CompanyID = DirectLcExpense_Header.CompanyID ) and DirectLcExpense_Header.status = 1
INNER JOIN AR_SET_Customer ON DirectLcExpense_Header.ClearingAgentID = AR_SET_Customer.CustomerID AND DirectLcExpense_Header.PeriodID = DirectLcExpense_Header.PeriodID AND DirectLcExpense_Header.Status = 1 AND AR_SET_Customer.Status = 1 {1} INNER JOIN AR_SET_BusinessPartnerTypes ON AR_SET_BusinessPartnerTypes.BusinessPartnerID = AR_SET_Customer.CustomerID --AND AR_SET_BusinessPartnerTypes.CompanyID = AR_SET_Customer.CompanyID AND AR_SET_BusinessPartnerTypes.PeriodID = AR_SET_Customer.PeriodID {0} INNER JOIN AR_SET_BusinessPartner ON AR_SET_BusinessPartner.BusinessPartnerID = AR_SET_BusinessPartnerTypes.TypeCode and AR_SET_BusinessPartner.BusinessPartnerName = 'Vendor' {7} WHERE DirectLcExpense_Header.CompanyID in @CompanyID and AR_SET_Customer.PeriodID = @PeriodID AND DirectLcExpense_Header.CreateDate BETWEEN @FromDate AND @ToDate And (SET_DocumentType.DocumentTypeID =@DocumentTypeiD Or @DocumentTypeiD is Null) --{3}
union all
-----------Sale Invoice Header Detail Data----------- SELECT SET_DocumentType.DocumentType, SAL_InvoiceHeader.CreateDate, SAL_InvoiceHeader.CompanyID, AR_SET_Customer.CustomerID, AR_SET_Customer.CustomerName AS BusinessPartnerName, SAL_InvoiceHeader.InvoiceID as SourceID, (case when Sal_InvoiceCustomerDetail.TransactionType ='Credit' or SET_DocumentType.DocumentType = 'Credit Note' then SUM(Sal_InvoiceCustomerDetail.Amount *-1) else SUM(Sal_InvoiceCustomerDetail.Amount) end )Amount, '0' AS InstrumentNo, '' AS Comments, '' as DetailNarration, '' as InvoiceNumbers, '' as InvoiceDocumentNo, ISNULL(SAL_InvoiceHeader.InvoiceNumber, 0) AS DocumentNo, SAL_InvoiceHeader.InvoiceDate AS DocumentDate, CASE WHEN GL_TransactionDetail.TransactionType = 'Debit' THEN ISNULL(SAL_InvoiceHeader.FreightAmount * -1, 0) else ISNULL(SAL_InvoiceHeader.FreightAmount, 0) end as FreightAmount , 0 As ForAlhajAmount ,AR_SET_BusinessPartner.BusinessPartnerName as BPType ,'' as GRN_NO,'' as PO_NO, '' AS SheetNo, '' AS FAX FROM SET_DocumentType INNER JOIN SAL_InvoiceHeader ON SET_DocumentType.CompanyID = SAL_InvoiceHeader.CompanyID AND SET_DocumentType.PeriodID = SAL_InvoiceHeader.PeriodID AND SET_DocumentType.DocumentTypeID = SAL_InvoiceHeader.InvoiceType inner join Sal_InvoiceCustomerDetail on Sal_InvoiceCustomerDetail.InvoiceHeaderID = SAL_InvoiceHeader.InvoiceID and Sal_InvoiceCustomerDetail.CompanyID = SAL_InvoiceHeader.CompanyID and Sal_InvoiceCustomerDetail.PeriodID = SAL_InvoiceHeader.PeriodID and Sal_InvoiceCustomerDetail.Status = 1 INNER JOIN AR_SET_Customer ON Sal_InvoiceCustomerDetail.CustomerID = AR_SET_Customer.CustomerID --AND Sal_InvoiceCustomerDetail.CompanyID = AR_SET_Customer.CompanyID AND Sal_InvoiceCustomerDetail.PeriodID = AR_SET_Customer.PeriodID AND SAL_InvoiceHeader.Status = 1 AND SAL_InvoiceHeader.StatusCode = 1 AND AR_SET_Customer.Status = 1
{1} INNER JOIN AR_SET_BusinessPartnerTypes ON AR_SET_BusinessPartnerTypes.BusinessPartnerID = AR_SET_Customer.CustomerID --AND AR_SET_BusinessPartnerTypes.CompanyID = AR_SET_Customer.CompanyID AND AR_SET_BusinessPartnerTypes.PeriodID = AR_SET_Customer.PeriodID AND AR_SET_BusinessPartnerTypes.TypeCode = Sal_InvoiceCustomerDetail.BusinessPartnerTypeID {0} inner JOIN AR_SET_BusinessPartner ON AR_SET_BusinessPartner.BusinessPartnerID = AR_SET_BusinessPartnerTypes.TypeCode LEFT JOIN GL_TransactionDetail ON GL_TransactionDetail.CodeCombinationID = SAL_InvoiceHeader.FreightCode AND GL_TransactionDetail.SourceHeaderID = SAL_InvoiceHeader.InvoiceID AND GL_TransactionDetail.CompanyID = SAL_InvoiceHeader.CompanyID AND GL_TransactionDetail.PeriodID = SAL_InvoiceHeader.PeriodID {7} LEFT JOIN SET_Department ON SET_Department.DepartmentID = GL_TransactionDetail.DepartmentID AND SET_Department.Status = 1 AND SET_Department.IsActive = 1 WHERE SAL_InvoiceHeader.CompanyID in @CompanyID and AR_SET_Customer.PeriodID = @PeriodID AND SAL_InvoiceHeader.InvoiceDate BETWEEN @FromDate AND @ToDate And (SET_DocumentType.DocumentTypeID =@DocumentTypeiD Or @DocumentTypeiD is Null) AND (SET_Department.DepartmentID = @DepartmentID OR @DepartmentID IS NULL) {3} GROUP BY SAL_InvoiceHeader.CreateDate,SAL_InvoiceHeader.CompanyID, AR_SET_Customer.CustomerID, AR_SET_Customer.CustomerName, SAL_InvoiceHeader.InvoiceID, Sal_InvoiceCustomerDetail.Amount, SAL_InvoiceHeader.InvoiceNumber, SAL_InvoiceHeader.InvoiceDate, SET_DocumentType.DocumentType, GL_TransactionDetail.TransactionType, SAL_InvoiceHeader.FreightAmount ,Sal_InvoiceCustomerDetail.TransactionType ,AR_SET_BusinessPartner.BusinessPartnerName
union all --RECEIPT TRANSACTION SELECT distinct SET_DocumentType.DocumentType, AR_ReceiptTransactionHeader.CreateDate, AR_ReceiptTransactionHeader.CompanyID, AR_SET_Customer.CustomerID, AR_SET_Customer.CustomerName AS BusinessPartnerName, AR_ReceiptTransactionHeader.ReceiptTransactionID as SourceID, Case when ( select Amount from AR_ReceiptAccountsDetail rad where rad.TransactionType = 'Credit' and rad.ReceiptHeaderID = AR_ReceiptAccountsDetail.ReceiptHeaderID and rad.ReceiptAccountID = AR_ReceiptAccountsDetail.ReceiptAccountID ) is null then AR_ReceiptTransactionHeader.Amount * -1 else AR_ReceiptTransactionHeader.Amount * -1 end as Amount,
STUFF((SELECT ', ' + PBD.InstrumentNo FROM AR_ReceiptBanksDetail PBD WHERE PBD.ReceiptHeaderID = AR_ReceiptTransactionHeader.ReceiptTransactionID FOR XML PATH('')), 1, 1, '') AS InstrumentNo , IsNull(AR_ReceiptTransactionHeader.Comments, '') + (Case When AR_ReceiptTransactionHeader.ReversalComments IS NULL Then '' Else ' ' + AR_ReceiptTransactionHeader.ReversalComments End) AS Comments, '' as DetailNarration, STUFF((SELECT ', ' + SAL_InvoiceHeader.invoicenumber FROM AR_ReceiptInvoicesDetail PBD inner join SAL_InvoiceHeader on SAL_InvoiceHeader.InvoiceID = PBD.InvoiceHeaderID and SAL_InvoiceHeader.Status = 1 and SAL_InvoiceHeader.CompanyID = PBD.CompanyID and SAL_InvoiceHeader.PeriodID = PBD.PeriodID WHERE PBD.ReceiptHeaderID = AR_ReceiptTransactionHeader.ReceiptTransactionID and PBD.CompanyID = AR_ReceiptTransactionHeader.CompanyID --and PBD.PeriodID = AR_ReceiptTransactionHeader.PeriodID FOR XML PATH('')), 1, 1, '') AS InvoiceNumbers, '' as InvoiceDocumentNo, ISNULL(AR_ReceiptTransactionHeader.DocumentNo, 0) AS DocumentNo, AR_ReceiptTransactionHeader.DocumentDate AS DocumentDate, 0 AS FreightAmount, 0 As ForAlhajAmount ,AR_SET_BusinessPartner.BusinessPartnerName as BPType ,'' as GRN_NO ,STUFF(( select distinct ', ' + convert(varchar(10),isnull(SAL_ContractHeader.ContractNo,SAL_OrderHeader.ContractNo)) from AR_ReceiptTransactionHeader recpt left join SAL_ContractHeader on SAL_ContractHeader.ContractID = recpt.SourceHeaderID and SAL_ContractHeader.CompanyID = recpt.CompanyID and SAL_ContractHeader.PeriodID = recpt.PeriodID
left join SAL_OrderHeader on SAL_OrderHeader.OrderID = recpt.SourceHeaderID and SAL_OrderHeader.CompanyID = recpt.CompanyID and SAL_OrderHeader.PeriodID = recpt.PeriodID
where recpt.ReceiptTransactionID = AR_ReceiptTransactionHeader.ReceiptTransactionID and recpt.CompanyID = AR_ReceiptTransactionHeader.CompanyID and recpt.PeriodID = AR_ReceiptTransactionHeader.PeriodID
FOR XML PATH('')), 1, 1, '') AS PO_NO, '' AS SheetNo, '' AS FAX FROM SET_DocumentType INNER JOIN AR_ReceiptTransactionHeader ON SET_DocumentType.CompanyID = AR_ReceiptTransactionHeader.CompanyID AND SET_DocumentType.PeriodID = AR_ReceiptTransactionHeader.PeriodID AND SET_DocumentType.DocumentTypeID = AR_ReceiptTransactionHeader.DocumentTypeID AND AR_ReceiptTransactionHeader.Status = 1 AND AR_ReceiptTransactionHeader.StatusCode = 1
--Left Join AR_ReceiptBanksDetail on AR_ReceiptBanksDetail.ReceiptBankID=AR_ReceiptTransactionHeader.ReceiptTransactionID --AND AR_ReceiptBanksDetail.CompanyID=AR_ReceiptTransactionHeader.CompanyID --AND AR_ReceiptBanksDetail.PeriodID=AR_ReceiptTransactionHeader.PeriodID --AND AR_ReceiptBanksDetail.Status=1
INNER JOIN AR_SET_Customer ON AR_ReceiptTransactionHeader.CustomerID = AR_SET_Customer.CustomerID --AND AR_ReceiptTransactionHeader.CompanyID = AR_SET_Customer.CompanyID AND AR_ReceiptTransactionHeader.PeriodID = AR_SET_Customer.PeriodID AND AR_SET_Customer.Status = 1 {1} INNER JOIN AR_SET_BusinessPartnerTypes ON AR_SET_BusinessPartnerTypes.BusinessPartnerID = AR_SET_Customer.CustomerID --AND AR_SET_BusinessPartnerTypes.CompanyID = AR_SET_Customer.CompanyID AND AR_SET_BusinessPartnerTypes.PeriodID = AR_SET_Customer.PeriodID AND AR_SET_BusinessPartnerTypes.TypeCode = AR_ReceiptTransactionHeader.BusinessPartnerTypeID {0} INNER JOIN AR_SET_BusinessPartner ON AR_SET_BusinessPartner.BusinessPartnerID = AR_SET_BusinessPartnerTypes.TypeCode Left Join AR_ReceiptAccountsDetail on AR_ReceiptAccountsDetail.CompanyID = AR_ReceiptTransactionHeader.CompanyID AND AR_ReceiptAccountsDetail.PeriodID = AR_ReceiptTransactionHeader.PeriodID AND AR_ReceiptAccountsDetail.ReceiptHeaderID = AR_ReceiptTransactionHeader.ReceiptTransactionID {7} WHERE AR_ReceiptTransactionHeader.CompanyID in @CompanyID and AR_SET_Customer.PeriodID = @PeriodID AND AR_ReceiptTransactionHeader.DocumentDate BETWEEN @FromDate AND @ToDate And (SET_DocumentType.DocumentTypeID =@DocumentTypeiD Or @DocumentTypeiD is Null) and AR_ReceiptTransactionHeader.ReceiptTransactionID not in ( select ReceiptHeaderID from AR_ReceiptCustomerDetail inner join AR_ReceiptTransactionHeader RecHDR on RecHDR.ReceiptTransactionID = AR_ReceiptTransactionHeader.ReceiptTransactionID and RecHDR.CompanyID = AR_ReceiptTransactionHeader.CompanyID and RecHDR.PeriodID = AR_ReceiptTransactionHeader.PeriodID inner join set_documentType on set_documentType.DocumentTypeID = AR_ReceiptTransactionHeader.DocumentTypeID and set_documentType.CompanyID = AR_ReceiptTransactionHeader.CompanyID and set_documentType.PeriodID = AR_ReceiptTransactionHeader.PeriodID {7} where AR_ReceiptCustomerDetail.ReceiptHeaderID = AR_ReceiptTransactionHeader.ReceiptTransactionID and AR_ReceiptCustomerDetail.CompanyID = AR_ReceiptTransactionHeader.CompanyID and AR_ReceiptCustomerDetail.PeriodID = AR_ReceiptTransactionHeader.PeriodID and set_documentType.documentType not like '%Advance Against SO%' and set_documentType.documentType not like '%sale invoice%' ) {4} GROUP BY AR_ReceiptTransactionHeader.CreateDate,AR_ReceiptTransactionHeader.CompanyID, AR_SET_Customer.CustomerID, AR_SET_Customer.CustomerName, AR_ReceiptTransactionHeader.ReceiptTransactionID, AR_ReceiptAccountsDetail.ReceiptHeaderID, AR_ReceiptAccountsDetail.ReceiptAccountID,AR_ReceiptAccountsDetail.Amount, AR_ReceiptTransactionHeader.Amount, AR_ReceiptTransactionHeader.DocumentNo, AR_ReceiptTransactionHeader.DocumentDate, SET_DocumentType.DocumentType, AR_ReceiptTransactionHeader.Comments, ReversalComments ,AR_ReceiptTransactionHeader.ReceiptTransactionID ,AR_SET_BusinessPartner.BusinessPartnerName,AR_ReceiptTransactionHeader.SourceHeaderID ,AR_ReceiptTransactionHeader.PeriodID UNION ALL -- Receipt Transaction Without Opening SELECT Distinct SET_DocumentType.DocumentType, AR_ReceiptTransactionHeader.CreateDate, AR_ReceiptTransactionHeader.CompanyID, AR_SET_Customer.CustomerID, AR_SET_Customer.CustomerName AS BusinessPartnerName, AR_ReceiptCustomerDetail.ReceiptHeaderID as SourceID, Case when AR_ReceiptCustomerDetail.TransactionType = 'Debit' then AR_ReceiptCustomerDetail.Amount else AR_ReceiptCustomerDetail.Amount * -1 end as Amount, AR_ReceiptBanksDetail.InstrumentNo, IsNull(AR_ReceiptTransactionHeader.Comments, '') + (Case When AR_ReceiptTransactionHeader.ReversalComments IS NULL Then '' Else ' ' + AR_ReceiptTransactionHeader.ReversalComments End) AS Comments, (SELECT TOP 1 Narration FROM AR_ReceiptCustomerDetail WHERE AR_ReceiptCustomerDetail.ReceiptHeaderID = AR_ReceiptTransactionHeader.ReceiptTransactionID and AR_ReceiptCustomerDetail.CompanyID = AR_ReceiptTransactionHeader.CompanyID and AR_ReceiptCustomerDetail.PeriodID = AR_ReceiptTransactionHeader.PeriodID and AR_ReceiptCustomerDetail.status = 1) as DetailNarration, '' as InvoiceNumbers, '' as InvoiceDocumentNo, ISNULL(AR_ReceiptTransactionHeader.DocumentNo, 0) AS DocumentNo, AR_ReceiptTransactionHeader.DocumentDate, 0 AS FreightAmount, 0 As ForAlhajAmount ,AR_SET_BusinessPartner.BusinessPartnerName as BPType ,'' as GRN_NO,'' as PO_NO, AR_ReceiptBanksDetail.SheetNo, AR_ReceiptBanksDetail.FAX FROM SET_DocumentType INNER JOIN AR_ReceiptTransactionHeader ON SET_DocumentType.CompanyID = AR_ReceiptTransactionHeader.CompanyID AND SET_DocumentType.PeriodID = AR_ReceiptTransactionHeader.PeriodID AND SET_DocumentType.DocumentTypeID = AR_ReceiptTransactionHeader.DocumentTypeID AND AR_ReceiptTransactionHeader.Status = 1 AND AR_ReceiptTransactionHeader.StatusCode = 1 INNER JOIN AR_ReceiptCustomerDetail on AR_ReceiptCustomerDetail.ReceiptHeaderID = AR_ReceiptTransactionHeader.ReceiptTransactionID and AR_ReceiptCustomerDetail.CompanyID = AR_ReceiptTransactionHeader.CompanyID and AR_ReceiptCustomerDetail.PeriodID = AR_ReceiptTransactionHeader.PeriodID and AR_ReceiptCustomerDetail.status = 1
Left Join AR_ReceiptBanksDetail on AR_ReceiptBanksDetail.ReceiptHeaderID=AR_ReceiptTransactionHeader.ReceiptTransactionID AND AR_ReceiptBanksDetail.ReceiptBankID = AR_ReceiptCustomerDetail.ReceiptCustomerID AND AR_ReceiptBanksDetail.CompanyID=AR_ReceiptTransactionHeader.CompanyID AND AR_ReceiptBanksDetail.PeriodID=AR_ReceiptTransactionHeader.PeriodID AND AR_ReceiptBanksDetail.Status=1
