ransactionHeader.PeriodID ,AR_SET_BusinessPartner.BusinessPartnerName,AR_ReceiptBanksDetail.SheetNo, AR_ReceiptBanksDetail.FAX UNION ALL -- Receipt Transaction [Only Opening]
SELECT Distinct SET_DocumentType.DocumentType, AR_ReceiptTransactionHeader.CreateDate, AR_ReceiptTransactionHeader.CompanyID, AR_SET_Customer.CustomerID, AR_SET_Customer.CustomerName AS BusinessPartnerName, AR_ReceiptCustomerDetail.ReceiptCustomerID as SourceID, Case when AR_ReceiptCustomerDetail.TransactionType = 'Debit' then AR_ReceiptCustomerDetail.Amount else AR_ReceiptCustomerDetail.Amount * -1 end as Amount, STUFF((SELECT ', ' + PBD.InstrumentNo FROM AR_ReceiptBanksDetail PBD WHERE PBD.ReceiptHeaderID = AR_ReceiptTransactionHeader.ReceiptTransactionID FOR XML PATH('')), 1, 1, '') AS InstrumentNo , IsNull(AR_ReceiptTransactionHeader.Comments, '') + (Case When AR_ReceiptTransactionHeader.ReversalComments IS NULL Then '' Else ' ' + AR_ReceiptTransactionHeader.ReversalComments End) AS Comments, AR_ReceiptCustomerDetail.Narration as DetailNarration, '' as InvoiceNumbers, '' as InvoiceDocumentNo, ISNULL(AR_ReceiptTransactionHeader.DocumentNo, 0) AS DocumentNo, AR_ReceiptTransactionHeader.DocumentDate, 0 AS FreightAmount, 0 As ForAlhajAmount ,AR_SET_BusinessPartner.BusinessPartnerName as BPType ,'' as GRN_NO,'' as PO_NO, '' AS SheetNo, '' AS FAX FROM SET_DocumentType INNER JOIN AR_ReceiptTransactionHeader ON SET_DocumentType.CompanyID = AR_ReceiptTransactionHeader.CompanyID AND SET_DocumentType.PeriodID = AR_ReceiptTransactionHeader.PeriodID AND SET_DocumentType.DocumentTypeID = AR_ReceiptTransactionHeader.DocumentTypeID AND AR_ReceiptTransactionHeader.Status = 1 AND AR_ReceiptTransactionHeader.StatusCode = 1 INNER JOIN AR_ReceiptCustomerDetail on AR_ReceiptCustomerDetail.ReceiptHeaderID = AR_ReceiptTransactionHeader.ReceiptTransactionID and AR_ReceiptCustomerDetail.CompanyID = AR_ReceiptTransactionHeader.CompanyID and AR_ReceiptCustomerDetail.PeriodID = AR_ReceiptTransactionHeader.PeriodID and AR_ReceiptCustomerDetail.status = 1 -- Left Join AR_ReceiptBanksDetail on AR_ReceiptBanksDetail.ReceiptBankID=AR_ReceiptTransactionHeader.ReceiptTransactionID --AND AR_ReceiptBanksDetail.CompanyID=AR_ReceiptTransactionHeader.CompanyID --AND AR_ReceiptBanksDetail.PeriodID=AR_ReceiptTransactionHeader.PeriodID --AND AR_ReceiptBanksDetail.Status=1 INNER JOIN AR_SET_Customer ON AR_ReceiptCustomerDetail.CustomerID = AR_SET_Customer.CustomerID --AND AR_ReceiptCustomerDetail.CompanyID = AR_SET_Customer.CompanyID AND AR_ReceiptCustomerDetail.PeriodID = AR_SET_Customer.PeriodID AND AR_SET_Customer.Status = 1 {1} INNER JOIN AR_SET_BusinessPartnerTypes ON AR_SET_BusinessPartnerTypes.BusinessPartnerID = AR_SET_Customer.CustomerID --AND AR_SET_BusinessPartnerTypes.CompanyID = AR_SET_Customer.CompanyID AND AR_SET_BusinessPartnerTypes.PeriodID = AR_SET_Customer.PeriodID AND AR_SET_BusinessPartnerTypes.TypeCode = AR_ReceiptCustomerDetail.BusinessPartnerTypeID {0} INNER JOIN AR_SET_BusinessPartner ON AR_SET_BusinessPartner.BusinessPartnerID = AR_SET_BusinessPartnerTypes.TypeCode LEFT Join AR_ReceiptAccountsDetail on AR_ReceiptAccountsDetail.CompanyID = AR_ReceiptTransactionHeader.CompanyID AND AR_ReceiptAccountsDetail.PeriodID = AR_ReceiptTransactionHeader.PeriodID AND AR_ReceiptAccountsDetail.ReceiptHeaderID = AR_ReceiptTransactionHeader.ReceiptTransactionID {7} WHERE AR_ReceiptTransactionHeader.CompanyID in @CompanyID and AR_SET_Customer.PeriodID = @PeriodID AND AR_ReceiptTransactionHeader.DocumentDate between @FromDate and @Todate and SET_DocumentType.DocumentType like '%opening%' And (SET_DocumentType.DocumentTypeID =@DocumentTypeiD Or @DocumentTypeiD is Null) {4} GROUP BY AR_ReceiptTransactionHeader.CreateDate,AR_ReceiptTransactionHeader.CompanyID, AR_SET_Customer.CustomerID, AR_SET_Customer.CustomerName, AR_ReceiptCustomerDetail.ReceiptCustomerID, AR_ReceiptCustomerDetail.TransactionType, AR_ReceiptCustomerDetail.Amount, AR_ReceiptTransactionHeader.Amount, AR_ReceiptTransactionHeader.DocumentNo, AR_ReceiptTransactionHeader.DocumentDate, SET_DocumentType.DocumentType, AR_ReceiptTransactionHeader.Comments, AR_ReceiptTransactionHeader.ReversalComments,AR_ReceiptCustomerDetail.Narration,AR_ReceiptTransactionHeader.ReceiptTransactionID ,AR_SET_BusinessPartner.BusinessPartnerName UNION ALL -- Commission On Receipt SELECT Distinct SET_DocumentType.DocumentType, AR_ReceiptTransactionHeader.CreateDate,AR_ReceiptTransactionHeader.CompanyID, AR_SET_Customer.CustomerID, AR_SET_Customer.CustomerName AS BusinessPartnerName, AR_ReceiptTransactionHeader.ReceiptTransactionID as SourceID, ((AR_ReceiptTransactionHeader.Amount * AR_ReceiptTransactionHeader.CommissionPercentage)/100) * -1 as Amount, STUFF((SELECT ', ' + PBD.InstrumentNo FROM AR_ReceiptBanksDetail PBD WHERE PBD.ReceiptHeaderID = AR_ReceiptTransactionHeader.ReceiptTransactionID FOR XML PATH('')), 1, 1, '') AS InstrumentNo , IsNull(AR_ReceiptTransactionHeader.Comments, '') + (Case When AR_ReceiptTransactionHeader.ReversalComments IS NULL Then '' Else ' ' + AR_ReceiptTransactionHeader.ReversalComments End) AS Comments, '' as DetailNarration, '' as InvoiceNumbers, '' as InvoiceDocumentNo, ISNULL(AR_ReceiptTransactionHeader.DocumentNo, 0) AS DocumentNo, AR_ReceiptTransactionHeader.DocumentDate AS DocumentDate, 0 AS FreightAmount, 0 As ForAlhajAmount ,AR_SET_BusinessPartner.BusinessPartnerName as BPType ,'' as GRN_NO,'' as PO_NO, '' AS SheetNo, '' AS FAX FROM SET_DocumentType INNER JOIN AR_ReceiptTransactionHeader ON SET_DocumentType.CompanyID = AR_ReceiptTransactionHeader.CompanyID AND SET_DocumentType.PeriodID = AR_ReceiptTransactionHeader.PeriodID AND SET_DocumentType.DocumentTypeID = AR_ReceiptTransactionHeader.DocumentTypeID AND AR_ReceiptTransactionHeader.Status = 1 AND AR_ReceiptTransactionHeader.StatusCode = 1 -- Left Join AR_ReceiptBanksDetail on AR_ReceiptBanksDetail.ReceiptBankID=AR_ReceiptTransactionHeader.ReceiptTransactionID --AND AR_ReceiptBanksDetail.CompanyID=AR_ReceiptTransactionHeader.CompanyID --AND AR_ReceiptBanksDetail.PeriodID=AR_ReceiptTransactionHeader.PeriodID --AND AR_ReceiptBanksDetail.Status=1
INNER JOIN AR_SET_Customer ON AR_ReceiptTransactionHeader.EmployeeID = AR_SET_Customer.CustomerID --AND AR_ReceiptTransactionHeader.CompanyID = AR_SET_Customer.CompanyID AND AR_ReceiptTransactionHeader.PeriodID = AR_SET_Customer.PeriodID AND AR_SET_Customer.Status = 1 {1} INNER JOIN AR_SET_BusinessPartnerTypes ON AR_SET_BusinessPartnerTypes.BusinessPartnerID = AR_SET_Customer.CustomerID --AND AR_SET_BusinessPartnerTypes.CompanyID = AR_SET_Customer.CompanyID AND AR_SET_BusinessPartnerTypes.PeriodID = AR_SET_Customer.PeriodID AND AR_SET_BusinessPartnerTypes.TypeCode = AR_ReceiptTransactionHeader.BusinessPartnerTypeID {0} INNER JOIN AR_SET_BusinessPartner ON AR_SET_BusinessPartner.BusinessPartnerID = AR_SET_BusinessPartnerTypes.TypeCode Left Join AR_ReceiptAccountsDetail on AR_ReceiptAccountsDetail.CompanyID = AR_ReceiptTransactionHeader.CompanyID AND AR_ReceiptAccountsDetail.PeriodID = AR_ReceiptTransactionHeader.PeriodID AND AR_ReceiptAccountsDetail.ReceiptHeaderID = AR_ReceiptTransactionHeader.ReceiptTransactionID {7} WHERE AR_ReceiptTransactionHeader.CompanyID in @CompanyID and AR_SET_Customer.PeriodID = @PeriodID AND AR_ReceiptTransactionHeader.DocumentDate BETWEEN @FromDate AND @ToDate And (SET_DocumentType.DocumentTypeID =@DocumentTypeiD Or @DocumentTypeiD is Null) {4} GROUP BY AR_ReceiptTransactionHeader.CreateDate,AR_ReceiptTransactionHeader.CompanyID, AR_SET_Customer.CustomerID, AR_SET_Customer.CustomerName, AR_ReceiptTransactionHeader.ReceiptTransactionID, AR_ReceiptTransactionHeader.CommissionPercentage, AR_ReceiptAccountsDetail.ReceiptHeaderID, AR_ReceiptAccountsDetail.ReceiptAccountID,AR_ReceiptAccountsDetail.Amount, AR_ReceiptTransactionHeader.Amount, AR_ReceiptTransactionHeader.DocumentNo, AR_ReceiptTransactionHeader.DocumentDate, SET_DocumentType.DocumentType, AR_ReceiptTransactionHeader.Comments, ReversalComments ,AR_ReceiptTransactionHeader.ReceiptTransactionID ,AR_SET_BusinessPartner.BusinessPartnerName -------- SALE DISCOUNT -----------
union All SELECT distinct SET_DocumentType.DocumentType, SAL_DiscountTransactionHeader.CreateDate, SAL_DiscountTransactionHeader.CompanyID, AR_SET_Customer.CustomerID, AR_SET_Customer.CustomerName AS BusinessPartnerName, SAL_DiscountTransactionHeader.DiscountTransactionHeaderID as SourceID, (SAL_DiscountTransactionHeader.CalculatedAmount * -1) as Amount, '0' AS InstrumentNo, '' AS Comments, '' as DetailNarration ,'' as InvoiceNumbers, '' as InvoiceDocumentNo, ISNULL(SAL_DiscountTransactionHeader.DiscountTransactionHeaderID, 0) AS DocumentNo, SAL_DiscountTransactionHeader.RunDateTime AS DocumentDate, 0 AS FreightAmount, 0 As ForAlhajAmount ,AR_SET_BusinessPartner.BusinessPartnerName as BPType ,'' as GRN_NO,'' as PO_NO, '' AS SheetNo, '' AS FAX FROM SET_DocumentType INNER JOIN SAL_DiscountTransactionHeader ON SET_DocumentType.CompanyID = SAL_DiscountTransactionHeader.CompanyID AND SET_DocumentType.PeriodID = SAL_DiscountTransactionHeader.PeriodID AND SET_DocumentType.DocumentTypeID = SAL_DiscountTransactionHeader.DocumentTypeID INNER JOIN AR_SET_Customer ON SAL_DiscountTransactionHeader.CustomerID = AR_SET_Customer.CustomerID --AND SAL_DiscountTransactionHeader.CompanyID = AR_SET_Customer.CompanyID AND SAL_DiscountTransactionHeader.PeriodID = AR_SET_Customer.PeriodID AND AR_SET_Customer.Status = 1 {1} INNER JOIN AR_SET_BusinessPartnerTypes ON AR_SET_BusinessPartnerTypes.BusinessPartnerID = AR_SET_Customer.CustomerID --AND AR_SET_BusinessPartnerTypes.CompanyID = AR_SET_Customer.CompanyID AND AR_SET_BusinessPartnerTypes.PeriodID = AR_SET_Customer.PeriodID {0} INNER JOIN AR_SET_BusinessPartner ON AR_SET_BusinessPartner.BusinessPartnerID = AR_SET_BusinessPartnerTypes.TypeCode {7} WHERE SAL_DiscountTransactionHeader.CompanyID in @CompanyID and AR_SET_Customer.PeriodID = @PeriodID AND SAL_DiscountTransactionHeader.RunDateTime BETWEEN @FromDate AND @ToDate And (SET_DocumentType.DocumentTypeID =@DocumentTypeiD Or @DocumentTypeiD is Null)
