select distinct FinTab.DocumentType, FinTab.CreateDate,CompanyID, FinTab.CustomerID, FinTab.BusinessPartnerName, FinTab.SourceID, FinTab.Amount, FinTab.InstrumentNo, FinTab.Narration as Comments,FinTab.DetailNarration , FinTab.InvoiceNumbers, FinTab.InvoiceDocumentNo, FinTab.DocumentNo , FinTab.DocumentDate, FinTab.FreightAmount, FinTab.ForAlhajAmount ,FinTab.BPType,GRN_NO,PO_NO,SheetNo,FAX from ( Select distinct GL_TransactionHeader.DocumentDate,GL_TransactionHeader.CreateDate,GL_TransactionHeader.CompanyID, Set_DocumentType.DocumentType ,Set_DocumentType.DocumentTypeID, Set_CostCenter.CostCenterName, AR_Set_Customer.CustomerID, AR_Set_Customer.CustomerName as BusinessPartnerName, GL_TransactionHeader.DocumentNo, '' as DetailNarration, ' ' as Narration, GL_TransactionDetail.CodeCombinationID as SupplierAccountCode, ( Case When GL_TransactionDetail.TransactionType = 'Debit' Then GL_TransactionDetail.Amount When GL_TransactionDetail.TransactionType = 'Credit' then GL_TransactionDetail.Amount * -1 Else 0 End ) as Amount, GL_codecombinationDetail.Description as CodeDescription ,'' AS InstrumentNo ,AR_InvoiceHeader.InvoiceNumber as InvoiceDocumentNo , 0 as FreightAmount , 0 As ForAlhajAmount ,AR_InvoiceHeader.VendorReferenceNumber as InvoiceNumbers ,STUFF(( select distinct ', ' + convert(varchar(10),INV_StockTransactionheader.DocumentNo) from INV_StockTransactionDetail inner join INV_StockTransactionheader on INV_StockTransactionheader.StockTransactionID = INV_StockTransactionDetail.StockTransactionID and INV_StockTransactionheader.CompanyID = INV_StockTransactionDetail.CompanyID and INV_StockTransactionheader.PeriodID = INV_StockTransactionDetail.PeriodID inner join AR_InvoiceDetail invDtl on invDtl.StockHeaderID = INV_StockTransactionDetail.StockTransactionID and invDtl.StockDetailID = INV_StockTransactionDetail.TransactionDetailID and invDtl.CompanyID = INV_StockTransactionDetail.CompanyID and invDtl.PeriodID = INV_StockTransactionDetail.PeriodID and invDtl.Status = 1 where INV_StockTransactionDetail.Status = 1 and invDtl.InvoiceHeaderID = AR_InvoiceDetail.InvoiceHeaderID and invDtl.CompanyID = AR_InvoiceDetail.CompanyID and invDtl.PeriodID = AR_InvoiceDetail.PeriodID FOR XML PATH('')), 1, 1, '') AS GRN_NO ,STUFF(( Select distinct ', ' + convert(varchar(10), AP_PurchaseOrderHeader.DocumentNumber) from AP_PurchaseOrderHeader left join AR_InvoiceDetail on AR_InvoiceDetail.PurchaseOrderHeaderID=AP_PurchaseOrderHeader.POHeaderID And AP_PurchaseOrderHeader.CompanyID=AR_InvoiceDetail.CompanyID And AP_PurchaseOrderHeader.PeriodID=AR_InvoiceDetail.PeriodID And AP_PurchaseOrderHeader.Status=1 Where AR_InvoiceDetail.InvoiceHeaderID=AR_InvoiceHeader.InvoiceID AND AR_InvoiceDetail.CompanyID=AR_InvoiceHeader.CompanyID And AR_InvoiceDetail.PeriodID=AR_InvoiceHeader.PeriodID AND AR_InvoiceDetail.Status=1
FOR XML PATH('')), 1, 1, '') AS PO_NO, '' AS SheetNo, '' AS FAX ,AR_SET_BusinessPartner.BusinessPartnerName as BPType ,INV_StockTransactionHeader.StockTransactionID as SourceID FROM INV_StockTransactionHeader INNER JOIN SET_DocumentType ON SET_DocumentType.CompanyID = INV_StockTransactionHeader.CompanyID AND SET_DocumentType.PeriodID = INV_StockTransactionHeader.PeriodID AND SET_DocumentType.DocumentTypeID = INV_StockTransactionHeader.DocumentTypeID and INV_StockTransactionHeader.status = 1
INNER JOIN AR_SET_Customer ON INV_StockTransactionHeader.BusinessPartnerID = AR_SET_Customer.CustomerID AND INV_StockTransactionHeader.PeriodID = AR_SET_Customer.PeriodID AND AR_SET_Customer.Status = 1
{1} inner join GL_TransactionHeader on GL_TransactionHeader.DocumentNo = INV_StockTransactionHeader.DocumentNo and GL_TransactionHeader.DocumentTypeID = SET_DocumentType.DocumentTypeID and INV_StockTransactionHeader.FiscalID = GL_TransactionHeader.FiscalID and GL_TransactionHeader.Status=1
INNER JOIN dbo.GL_TransactionDetail ON GL_TransactionHeader.TransactionID = GL_TransactionDetail.TransactionID AND GL_TransactionHeader.PeriodID = GL_TransactionDetail.PeriodID AND GL_TransactionHeader.CompanyID = GL_TransactionDetail.CompanyID AND GL_TransactionDetail.TransactionType = 'Debit' AND GL_TransactionDetail.Status=1 Inner JOIN AR_SET_BusinessPartnerTypes ON AR_SET_BusinessPartnerTypes.BusinessPartnerID = INV_StockTransactionHeader.BusinessPartnerID AND AR_SET_BusinessPartnerTypes.PeriodID = INV_StockTransactionHeader.PeriodID AND AR_SET_BusinessPartnerTypes.FK_CodeCombinationID = GL_TransactionDetail.CodeCombinationID {0} INNER JOIN AR_SET_BusinessPartner ON AR_SET_BusinessPartner.BusinessPartnerID = INV_StockTransactionHeader.BusinessPartnerTypeID {7}
Left Join Set_CostCenter On Set_CostCenter.CostCenterID = GL_TransactionDetail.CostCenterID inner join GL_codecombinationDetail on GL_codecombinationDetail.CodeCombinationID = GL_TransactionDetail.CodeCombinationID
