) As FinTab Group By FinTab.DocumentDate,CreateDate,CompanyID, FinTab.DocumentType,FinTab.DocumentTypeID, FinTab.CostCenterName , FinTab.CustomerID, FinTab.BusinessPartnerName, FinTab.DocumentNo, Fintab.Narration, FinTab.SupplierAccountCode, FinTab.CodeDescription,InstrumentNo,FinTab.InvoiceNumbers,GRN_NO,PO_NO,SheetNo,FAX, FinTab.SourceID,FinTab.Amount ,FinTab.DetailNarration,FinTab.InvoiceDocumentNo,FinTab.FreightAmount,FinTab.ForAlhajAmount,FinTab.BPType
