------------------------------------- KNON of Advance cOPY OF 2 Non GST SELECT distinct SET_DocumentType.DocumentType, AR_InvoiceHeader.CreateDate, AR_InvoiceHeader.CompanyID, AR_SET_Customer.CustomerID, AR_SET_Customer.CustomerName AS BusinessPartnerName, GL_TransactionDetail.SerialNo + 1 as SourceID, (GL_TransactionDetail.Amount * -1) as Amount, '0' AS InstrumentNo, '' AS Comments, '' as DetailNarration ,'' as InvoiceNumbers, '' as InvoiceDocumentNo, ISNULL(AR_InvoiceHeader.invoiceNumber, 0) AS DocumentNo, AR_InvoiceHeader.invoiceDate AS DocumentDate, 0 AS FreightAmount, 0 As ForAlhajAmount ,AR_SET_BusinessPartner.BusinessPartnerName as BPType ,'' as GRN_NO,'' as PO_NO, '' AS SheetNo, '' AS FAX
FROM SET_DocumentType INNER JOIN AR_InvoiceHeader ON SET_DocumentType.CompanyID = AR_InvoiceHeader.CompanyID AND SET_DocumentType.PeriodID = AR_InvoiceHeader.PeriodID AND SET_DocumentType.DocumentTypeID = AR_InvoiceHeader.InvoiceType AND AR_InvoiceHeader.Status = 1 AND AR_InvoiceHeader.StatusCode = 1 INNER JOIN AR_SET_Customer ON AR_InvoiceHeader.VendorID = AR_SET_Customer.CustomerID --AND AR_InvoiceHeader.CompanyID = AR_SET_Customer.CompanyID AND AR_InvoiceHeader.PeriodID = AR_SET_Customer.PeriodID AND AR_SET_Customer.Status = 1 {1} inner join GL_TransactionHeader on GL_TransactionHeader.DocumentNo = AR_InvoiceHeader.InvoiceNumber and GL_TransactionHeader.DocumentTypeID = AR_InvoiceHeader.InvoiceType and GL_TransactionHeader.FiscalID = AR_InvoiceHeader.FiscalID INNER JOIN dbo.GL_TransactionDetail ON dbo.GL_TransactionHeader.TransactionID = dbo.GL_TransactionDetail.TransactionID AND dbo.GL_TransactionHeader.PeriodID = dbo.GL_TransactionDetail.PeriodID AND dbo.GL_TransactionHeader.CompanyID = dbo.GL_TransactionDetail.CompanyID
AND (dbo.GL_TransactionDetail.CodeCombinationID In (SELECT Distinct DefaultAccountCode FROM dbo.SET_DocumentType WHERE (DocumentType Like 'Advance Against PO%') AND (CompanyID in @CompanyID) AND (PeriodID = @PeriodID))) AND (dbo.GL_TransactionDetail.TransactionType = 'Credit')
LEFT JOIN AR_InvoiceDetail on AR_InvoiceDetail.CompanyID = AR_InvoiceHeader.CompanyID and AR_InvoiceDetail.PeriodID = AR_InvoiceHeader.PeriodID and AR_InvoiceDetail.InvoiceHeaderID = AR_InvoiceHeader.InvoiceID LEFT JOIN AR_InvoiceSupplierDetail on AR_InvoiceSupplierDetail.CompanyID = AR_InvoiceHeader.CompanyID and AR_InvoiceSupplierDetail.PeriodID = AR_InvoiceHeader.PeriodID and AR_InvoiceSupplierDetail.InvoiceHeaderID = AR_InvoiceHeader.InvoiceID and AR_InvoiceSupplierDetail.status = 1 LEFT JOIN AR_SET_Customer ASCUS ON AR_InvoiceSupplierDetail.SupplierID = ASCUS.CustomerID --AND AR_InvoiceSupplierDetail.CompanyID = ASCUS.CompanyID AND AR_InvoiceSupplierDetail.PeriodID = ASCUS.PeriodID AND ASCUS.Status = 1 left JOIN AR_SET_BusinessPartnerTypes ON AR_SET_BusinessPartnerTypes.BusinessPartnerID = AR_InvoiceHeader.vENDORid --AND AR_SET_BusinessPartnerTypes.CompanyID = AR_InvoiceHeader.CompanyID AND AR_SET_BusinessPartnerTypes.PeriodID = AR_InvoiceHeader.PeriodID --AND AR_SET_BusinessPartnerTypes.TypeCode = AR_InvoiceSupplierDetail.BusinessPartnerTypeID AND AR_SET_BusinessPartnerTypes.FK_CodeCombinationID = GL_TransactionDetail.CodeCombinationID
LEFT JOIN AR_SET_BusinessPartner ON AR_SET_BusinessPartner.BusinessPartnerID = AR_SET_BusinessPartnerTypes.TypeCode
LEFT JOIN SET_Department ON SET_Department.DepartmentID = GL_TransactionDetail.DepartmentID AND SET_Department.Status = 1 AND SET_Department.IsActive = 1
WHERE AR_InvoiceHeader.CompanyID in @CompanyID AND AR_InvoiceHeader.PeriodID = @PeriodId AND AR_InvoiceHeader.InvoiceDate BETWEEN @FromDate AND @ToDate And (SET_DocumentType.DocumentTypeID =@DocumentTypeiD Or @DocumentTypeiD is Null) and isnull(GL_TransactionDetail.Narration,'') not like '%GST%' and isnull(AR_SET_BusinessPartner.BusinessPartnerName,'') not like '%GST%' AND (SET_Department.DepartmentID = @DepartmentID OR @DepartmentID IS NULL) {0} {5}
{10}
{11}
{12}
UNION ALL
----Sales Invoice Return SELECT SET_DocumentType.DocumentType, SAL_ReverseHeader.CreateDate, SAL_ReverseHeader.CompanyID, AR_SET_Customer.CustomerID, AR_SET_Customer.CustomerName AS Name, SAL_ReverseHeader.ReverseHeaderID as SourceID, --case when SET_DocumentType.DocumentType = 'Credit Note' then SUM(ABS(SAL_ReverseDetail.ReversedAmount * -1)) else --SUM(ABS(SAL_ReverseDetail.ReversedAmount* -1)) end as Amount, SUM(SAL_ReverseDetail.ReversedAmount) * -1 as Amount, '0' AS InstrumentNo, GL_TransactionHeader.Narration AS Comments, '' as DetailNarration , SAL_InvoiceHeader.InvoiceNumber as InvoiceNumbers, SAL_InvoiceHeader.InvoiceNumber as InvoiceDocumentNo, ISNULL(SAL_ReverseHeader.DocumentNo, 0) AS DocumentNo, SAL_ReverseHeader.CreateDate AS DocumentDate, 0 as FreightAmount , 0 As ForAlhajAmount
,AR_SET_BusinessPartner.BusinessPartnerName as BPType,'' as GRN_NO,'' as PO_NO, '' AS SheetNo, '' AS FAX FROM SET_DocumentType Inner join SAL_ReverseHeader on SAL_ReverseHeader.CompanyID= SET_DocumentType.CompanyID and SAL_ReverseHeader.PeriodID = SET_DocumentType.PeriodID and SAL_ReverseHeader.DocumentTypeID = SET_DocumentType.DocumentTypeID and SAL_ReverseHeader.Status = 1 and SET_DocumentType.Status = 1
inner join SAL_ReverseDetail on SAL_ReverseDetail.ReverseHeaderID = SAL_ReverseHeader.ReverseHeaderID and SAL_ReverseHeader.CompanyID= SAL_ReverseDetail.CompanyID and SAL_ReverseHeader.PeriodID = SAL_ReverseDetail.PeriodID and SAL_ReverseDetail.Status = 1
inner join SAL_InvoiceDetail on SAL_InvoiceDetail.InvoiceDetailID = SAL_ReverseDetail.SourceDetailID and SAL_InvoiceDetail.InvoiceHeaderID = SAL_ReverseDetail.SourceHeaderID and SAL_InvoiceDetail.CompanyID = SAL_ReverseDetail.CompanyID and SAL_InvoiceDetail.Status = 1
inner join SAL_InvoiceHeader on SAL_InvoiceHeader.InvoiceID =SAL_InvoiceDetail.InvoiceHeaderID and SAL_InvoiceHeader.InvoiceNumber = SAL_ReverseDetail.SourceCode and SAL_InvoiceHeader.InvoiceType = SAL_ReverseDetail.SourceDocumentTypeID and SAL_InvoiceHeader.status = 1 and SAL_InvoiceHeader.CompanyID = SAL_ReverseDetail.CompanyID and SAL_InvoiceHeader.CompanyID = SAL_InvoiceDetail.CompanyID
left join GL_TransactionHeader on GL_TransactionHeader.DocumentNo = SAL_ReverseHeader.DocumentNo and GL_TransactionHeader.DocumentTypeID = SAL_ReverseHeader.DocumentTypeID and GL_TransactionHeader.CompanyID = SAL_ReverseHeader.CompanyID and GL_TransactionHeader.PeriodID = SAL_ReverseHeader.PeriodID and GL_TransactionHeader.FiscalID = SAL_ReverseHeader.FiscalID and GL_TransactionHeader.Status = 1
INNER JOIN AR_SET_Customer ON SAL_InvoiceHeader.CustomerID = AR_SET_Customer.CustomerID AND SAL_InvoiceHeader.CompanyID = AR_SET_Customer.CompanyID AND SAL_InvoiceHeader.PeriodID = AR_SET_Customer.PeriodID AND SAL_InvoiceHeader.Status = 1 AND SAL_InvoiceHeader.StatusCode = 1 AND AR_SET_Customer.Status = 1 AND AR_SET_Customer.IsActive = 1 {1} INNER JOIN AR_SET_BusinessPartnerTypes ON AR_SET_BusinessPartnerTypes.BusinessPartnerID = AR_SET_Customer.CustomerID AND AR_SET_BusinessPartnerTypes.CompanyID = AR_SET_Customer.CompanyID AND AR_SET_BusinessPartnerTypes.PeriodID = AR_SET_Customer.PeriodID {0} INNER JOIN AR_SET_BusinessPartner ON AR_SET_BusinessPartner.BusinessPartnerID = AR_SET_BusinessPartnerTypes.TypeCode AND AR_SET_BusinessPartner.BusinessPartnerName = 'Local Sale Debtor - Sugar'
{7} WHERE SAL_ReverseHeader.CompanyID in @CompanyID AND SAL_ReverseHeader.PeriodID = @PeriodID AND SAL_ReverseHeader.CreateDate BETWEEN @FromDate AND @ToDate and SAL_ReverseHeader.StatusCode = 1 {3} GROUP BY SAL_InvoiceHeader.CreateDate, AR_SET_Customer.CustomerID, AR_SET_Customer.CustomerName,AR_SET_Customer.ContactNumber , AR_SET_Customer.ContactPerson , AR_SET_Customer.AddressLine1,SAL_ReverseHeader.CreateDate,SAL_ReverseHeader.ReverseHeaderID, SET_DocumentType.DocumentType ,SAL_ReverseHeader.DocumentNo ,SAL_ReverseHeader.CompanyID,SAL_InvoiceHeader.InvoiceNumber,GL_TransactionHeader.Narration,AR_SET_BusinessPartner.BusinessPartnerName
union all
-- Invoice Discount
SELECT distinct SET_DocumentType.DocumentType, AR_InvoiceHeader.CreateDate as CreateDate, AR_InvoiceHeader.CompanyID, AR_SET_Customer.CustomerID, AR_SET_Customer.CustomerName AS BusinessPartnerName, AR_InvoiceHeader.InvoiceID as SourceID, sum(isnull(AR_InvoiceDetail.DiscountAmountTaken,0)) as Amount, '0' AS InstrumentNo, '' AS Comments, '' AS DetailNarration, AR_InvoiceHeader.VendorReferenceNumber as InvoiceNumbers, '' as InvoiceDocumentNo, ISNULL(AR_InvoiceHeader.InvoiceNumber, 0) AS DocumentNo, AR_InvoiceHeader.InvoiceDate AS DocumentDate, 0 AS FreightAmount, 0 As ForAlhajAmount ,AR_SET_BusinessPartner.BusinessPartnerName as BPType --,'' as BPType --,'' as GRN_NO,'' as PO_NO
,STUFF(( select distinct ', ' + convert(varchar(10),INV_StockTransactionheader.DocumentNo) from INV_StockTransactionDetail inner join INV_StockTransactionheader on INV_StockTransactionheader.StockTransactionID = INV_StockTransactionDetail.StockTransactionID and INV_StockTransactionheader.CompanyID = INV_StockTransactionDetail.CompanyID and INV_StockTransactionheader.PeriodID = INV_StockTransactionDetail.PeriodID inner join AR_InvoiceDetail invDtl on invDtl.StockHeaderID = INV_StockTransactionDetail.StockTransactionID and invDtl.StockDetailID = INV_StockTransactionDetail.TransactionDetailID and invDtl.CompanyID = INV_StockTransactionDetail.CompanyID and invDtl.PeriodID = INV_StockTransactionDetail.PeriodID and invDtl.Status = 1 where INV_StockTransactionDetail.Status = 1 and invDtl.InvoiceHeaderID = AR_InvoiceDetail.InvoiceHeaderID and invDtl.CompanyID = AR_InvoiceDetail.CompanyID and invDtl.PeriodID = AR_InvoiceDetail.PeriodID FOR XML PATH('')), 1, 1, '') AS GRN_NO ,STUFF(( Select distinct ', ' + convert(varchar(10), AP_PurchaseOrderHeader.DocumentNumber) from AP_PurchaseOrderHeader left join AR_InvoiceDetail on AR_InvoiceDetail.PurchaseOrderHeaderID=AP_PurchaseOrderHeader.POHeaderID And AP_PurchaseOrderHeader.CompanyID=AR_InvoiceDetail.CompanyID And AP_PurchaseOrderHeader.PeriodID=AR_InvoiceDetail.PeriodID And AP_PurchaseOrderHeader.Status=1 Where AR_InvoiceDetail.InvoiceHeaderID=AR_InvoiceHeader.InvoiceID AND AR_InvoiceDetail.CompanyID=AR_InvoiceHeader.CompanyID And AR_InvoiceDetail.PeriodID=AR_InvoiceHeader.PeriodID AND AR_InvoiceDetail.Status=1
FOR XML PATH('')), 1, 1, '') AS PO_NO, '' AS SheetNo, '' AS FAX
FROM AR_InvoiceHeader inner join AR_InvoiceDetail on AR_InvoiceDetail.InvoiceHeaderID = AR_InvoiceHeader.InvoiceID and AR_InvoiceDetail.CompanyID = AR_InvoiceHeader.CompanyID and AR_InvoiceDetail.PeriodID = AR_InvoiceHeader.PeriodID INNER JOIN SET_DocumentType ON AR_InvoiceHeader.InvoiceType = SET_DocumentType.DocumentTypeID and AR_InvoiceHeader.CompanyID = SET_DocumentType.CompanyID INNER JOIN AR_SET_Customer ON AR_SET_Customer.CustomerID = AR_InvoiceHeader.VendorID AND AR_SET_Customer.Status = 1 {1}
left JOIN AR_SET_BusinessPartnerTypes ON AR_SET_BusinessPartnerTypes.BusinessPartnerID = AR_InvoiceHeader.VendorID AND AR_SET_BusinessPartnerTypes.PeriodID = AR_InvoiceHeader.PeriodID AND AR_SET_BusinessPartnerTypes.TypeCode = AR_InvoiceHeader.BusinessPartnerTypeID LEFT JOIN AR_SET_BusinessPartner ON AR_SET_BusinessPartner.BusinessPartnerID = AR_SET_BusinessPartnerTypes.TypeCode
WHERE AR_InvoiceHeader.CompanyID in @CompanyID AND AR_InvoiceHeader.PeriodID = @PeriodId AND AR_InvoiceHeader.InvoiceDate BETWEEN @FromDate AND @ToDate {0} {5} group by SET_DocumentType.DocumentType, AR_InvoiceHeader.CreateDate , AR_InvoiceHeader.CompanyID,AR_SET_Customer.CustomerID, AR_SET_Customer.CustomerName ,AR_InvoiceHeader.InvoiceID,AR_InvoiceHeader.InvoiceNumber,AR_InvoiceHeader.InvoiceDate,AR_SET_BusinessPartner.BusinessPartnerName ,AR_InvoiceDetail.InvoiceHeaderID,AR_InvoiceDetail.CompanyID,AR_InvoiceDetail.PeriodID,AR_InvoiceHeader.PeriodID ,AR_InvoiceHeader.VendorReferenceNumber
) AS FINTAB GROUP BY DocumentType, CreateDate,CompanyID, CustomerID, NAME, SourceID, InstrumentNo, Comments,DetailNarration, InvoiceNumbers, InvoiceDocumentNo, DocumentNo, DocumentDate, FreightAmount, ForAlhajAmount ,BPType ,GRN_NO,PO_NO,SheetNo,FAX ) as TAb -- For Transation type Filter {2} ) as FinalTAB Left Join HRMS_Set_Employee on HRMS_Set_Employee.FK_CustomerID = FinalTAB.CustomerID {13} where FinalTAB.Amount <> 0 {14} Order By DocumentDate
